local W, H = SCREEN_W, SCREEN_H          -- 256 x 256
local TS, CS = 16, 16                    -- tile pixels; chunk tiles (a chunk is one screen)
local CPX = TS * CS
local RING = 4                           -- the map holds 4 x 4 chunks
local RT = RING * CS                     -- ... that is 64 x 64 tiles
local SW8 = SHEET_W // 8                 -- map cells per sheet row
local SEED = 1887
local LEVELS, AMBIENT = 8, 1
local MARGIN = 112                       -- chunks this close to the view are made ahead
local floor, sin, cos, sqrt, abs, min, max = math.floor, math.sin, math.cos, math.sqrt, math.abs, math.min, math.max
local PI = math.pi

----------------------------------------------------------------- numbers

local function hash(a, b, c)
  local h = (a * 374761393 + b * 668265263 + c * 2246822519 + SEED * 3266489917) & 0xFFFFFFFF
  h = ((h ~ (h >> 15)) * 2246822519) & 0xFFFFFFFF
  h = ((h ~ (h >> 13)) * 3266489917) & 0xFFFFFFFF
  return h ~ (h >> 16)
end

local function h01(a, b, c) return hash(a, b, c) / 4294967296.0 end

-- a counter run through a mixing function: every number is well mixed,
-- the first ones after the seed too
local function newrng(seed)
  local s = seed & 0xFFFFFFFF
  return function()
    s = (s + 0x9E3779B9) & 0xFFFFFFFF
    local z = ((s ~ (s >> 16)) * 0x85EBCA6B) & 0xFFFFFFFF
    z = ((z ~ (z >> 13)) * 0xC2B2AE35) & 0xFFFFFFFF
    return (z ~ (z >> 16)) / 4294967296.0
  end
end

local function irange(r, a, b) return a + floor(r() * (b - a + 1)) end
local function pick(r, t) return t[floor(r() * #t) + 1] end
local function key2(a, b) return a * 1000003 + b end
local function fdiv(a, b) return floor(a) // b end   -- an integer, from pixels that may not be

----------------------------------------------------------------- the street plan
-- Streets run between the chunks, from corner to corner: every chunk is a
-- block with a street on each side (a few are missing), winding, of its own
-- width and paving. Corners, sides and districts depend only on their
-- coordinates, so neighbouring chunks agree on the streets they share.

local PV_COBBLE, PV_SETTS, PV_FLAGS, PV_ALLEY, PV_WARM, PV_MARBLE, PV_DARK, PV_WET = 1, 2, 3, 4, 5, 6, 7, 8

local corners, edges, districts = {}, {}, {}

local function corner(i, j)
  local k = key2(i, j)
  local c = corners[k]
  if not c then
    local h = hash(i, j, 1)
    c = { x = i * CS + (h % 5) - 2, y = j * CS + ((h >> 3) % 5) - 2,
          plaza = (h >> 6) % 100 < 18, r = 3.2 + ((h >> 13) % 3) * 0.6 }
    corners[k] = c
  end
  return c
end

-- the street from corner (i, j) eastwards (dir 0) or southwards (dir 1)
local function edge(i, j, dir)
  local k = key2(i, j) * 2 + dir
  local e = edges[k]
  if e == nil then
    local h = hash(i, j, 2 + dir)
    if h % 100 < 12 and not (abs(i) <= 1 and abs(j) <= 1) then
      e = false
    else
      local a = corner(i, j)
      local b = dir == 0 and corner(i + 1, j) or corner(i, j + 1)
      local w = 3 + (h >> 8) % 3
      local p = (h >> 24) % 6
      e = { a = a, b = b, dir = dir, hw = w / 2,
            A = ((h >> 12) % 61) / 10 - 3.0, B = ((h >> 18) % 21) / 10 - 1.0,
            pave = w == 5 and PV_SETTS or (p == 0 and PV_WARM or p == 1 and PV_WET or PV_COBBLE) }
      -- how far across its line the street can reach: tiles further are not on it
      local va, vb = dir == 0 and a.y or a.x, dir == 0 and b.y or b.x
      local reach = abs(e.A) + abs(e.B) + e.hw + 0.5
      e.lo, e.hi = min(va, vb) - reach, max(va, vb) + reach
    end
    edges[k] = e
  end
  return e
end

local function edge_dist(e, x, y)
  local a, b = e.a, e.b
  local u, v, ua, va, ub, vb
  if e.dir == 0 then u, v, ua, va, ub, vb = x, y, a.x, a.y, b.x, b.y
  else u, v, ua, va, ub, vb = y, x, a.y, a.x, b.y, b.x end
  if u < ua or u > ub then
    local du, dv
    if u < ua then du, dv = u - ua, v - va else du, dv = u - ub, v - vb end
    return sqrt(du * du + dv * dv)
  end
  local t = (u - ua) / (ub - ua)
  local c = va + (vb - va) * t + e.A * sin(PI * t) + e.B * sin(2 * PI * t)
  return abs(v - c)
end

local NAME_A = { "Ash", "Raven", "Gaunt", "Black", "Mourn", "Hollow", "Wither", "Crane", "Vigil", "Ember",
  "Gallows", "Iron", "Bell", "Thorn", "Grave", "Lantern", "Crow", "Cinder", "Moth", "Pale", "Weeping",
  "Lamb", "Tallow", "Bone", "Fog", "Wick", "Rook", "Gloam", "Candle", "Mire", "Saint Agnes", "Old Mill" }
local NAME_B = { " Lane", " Row", " Street", " Close", " Walk", " Yard", " Court", " Alley", " Hill", " Way" }
local SAINTS = { "St. Agnes", "St. Cyril", "St. Edith", "St. Ludo", "St. Mora", "St. Bram", "the Vigil" }

local function district(cx, cy)
  local k = key2(cx, cy)
  local d = districts[k]
  if d then return d end
  local h = hash(cx, cy, 7)
  local v = (h % 1000) / 1000
  local kind = "town"
  if cx == 0 and cy == 0 then kind = "square"
  elseif v < 0.10 then kind = "cemetery"
  elseif v < 0.17 then kind = "park"
  elseif v < 0.24 then kind = "square"
  elseif v < 0.29 then kind = "pyre"
  elseif v < 0.34 then kind = "chapel" end
  d = { kind = kind }
  if kind == "square" then d.plaza, d.prx, d.pry, d.pcy = PV_FLAGS, 5.6, 5.0, 8
  elseif kind == "pyre" then d.plaza, d.prx, d.pry, d.pcy = PV_FLAGS, 5.2, 4.6, 8
  elseif kind == "chapel" then d.plaza, d.prx, d.pry, d.pcy = PV_MARBLE, 5.4, 2.4, 13.0 end
  if kind == "town" and (h >> 12) % 100 < 40 then
    d.alley = { dir = (h >> 20) % 2, p = 5 + (h >> 22) % 6, k = 1 + (h >> 25) % 2, ph = (h >> 27) % 6 }
  end
  local a = NAME_A[(h >> 3) % #NAME_A + 1]
  local s = SAINTS[(h >> 9) % #SAINTS + 1]
  if kind == "cemetery" then d.name = a .. " Cemetery"
  elseif kind == "park" then d.name = a .. " Gardens"
  elseif kind == "square" then d.name = a .. " Square"
  elseif kind == "pyre" then d.name = "The " .. a .. " Pyre"
  elseif kind == "chapel" then d.name = "Chapel of " .. s
  else d.name = a .. NAME_B[(h >> 14) % #NAME_B + 1] end
  districts[k] = d
  return d
end

-- the sides of chunk (cx, cy), and the streets that meet at its corners
local function near_edges(cx, cy)
  local t = {}
  local list = {
    { cx, cy, 0 }, { cx, cy + 1, 0 }, { cx, cy, 1 }, { cx + 1, cy, 1 },
    { cx - 1, cy, 0 }, { cx + 1, cy, 0 }, { cx - 1, cy + 1, 0 }, { cx + 1, cy + 1, 0 },
    { cx, cy - 1, 1 }, { cx + 1, cy - 1, 1 }, { cx, cy + 1, 1 }, { cx + 1, cy + 1, 1 },
  }
  for _, l in ipairs(list) do
    local e = edge(l[1], l[2], l[3])
    if e then t[#t + 1] = e end
  end
  return t
end

-- paving of world tile (tx, ty), 0 = not a street
local function road_at(tx, ty, ne)
  local x, y = tx + 0.5, ty + 0.5
  local cx, cy = tx // CS, ty // CS
  for dj = 0, 1 do
    for di = 0, 1 do
      local c = corner(cx + di, cy + dj)
      if c.plaza then
        local dx, dy = x - c.x, y - c.y
        if dx * dx + dy * dy < c.r * c.r then return PV_FLAGS end
      end
    end
  end
  local d = district(cx, cy)
  local lx, ly = x - cx * CS, y - cy * CS
  if d.plaza then
    local dx, dy = (lx - 8) / d.prx, (ly - d.pcy) / d.pry
    if dx * dx + dy * dy < 1 then return d.plaza end
  end
  local al = d.alley
  if al then
    local u, v = lx, ly
    if al.dir == 1 then u, v = ly, lx end
    if abs(v - (al.p + 1.4 * sin(u / CS * PI * al.k + al.ph))) < 1.0 then return PV_ALLEY end
  end
  ne = ne or near_edges(cx, cy)
  for i = 1, #ne do
    local e = ne[i]
    local v = e.dir == 0 and y or x
    if v > e.lo and v < e.hi and edge_dist(e, x, y) < e.hw then return e.pave end
  end
  return 0
end

----------------------------------------------------------------- chunks

local K_FREE, K_ROAD, K_WALK, K_HOUSE, K_YARD, K_GRASS, K_PATH = 0, 1, 2, 3, 4, 5, 6
local FMATS = { "brick", "ashlar", "stucco", "dark", "brick", "stucco" }
local RMATS = { "slate", "tile", "lead", "copper", "slate", "slate", "tile" }
local GRAVES = { "grave_round", "grave_round2", "grave_cross", "grave_celtic", "grave_obelisk", "grave_broken",
  "grave_slab" }

local lamp_state = {}                    -- lamps lit by the hunter: key -> true
local lamps_lit = 0
local chunks, slots = {}, {}

-- objects: { s = sprite, x, y (the base, world pixels), z = sort key, ... }
local function add_obj(ch, name, x, y, z, col)
  local s = SPR[name]
  local o = { s = s, x = x, y = y, z = z or y, name = name }
  ch.objs[#ch.objs + 1] = o
  if col then ch.cols[#ch.cols + 1] = { x = x, y = y + (col.dy or 0), rx = col[1], ry = col[2] } end
  return o
end

local function add_light(ch, x, y, r, lv, fl, dither)
  ch.lights[#ch.lights + 1] = { x = x, y = y, r = r, lv = lv, fl = fl or 0, d = dither or 0.5,
    seed = (x * 7 + y * 13) % 97 }
end

local function gen(ch)
  local cx, cy = ch.cx, ch.cy
  local tx0, ty0 = cx * CS, cy * CS
  local px0, py0 = tx0 * TS, ty0 * TS
  local d = district(cx, cy)
  local r = newrng(hash(cx, cy, 11))
  local ne = near_edges(cx, cy)

  -- the streets over the chunk and one tile around it
  local road = {}
  for ly = -1, CS do
    local row = (ly + 1) * 18 + 2
    for lx = -1, CS do road[row + lx] = road_at(tx0 + lx, ty0 + ly, ne) end
  end
  local function RD(lx, ly) return road[(ly + 1) * 18 + 2 + lx] end

  local kind, solid, A, B = {}, {}, {}, {}
  ch.kind, ch.solid = kind, solid
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      local i = ly * CS + lx + 1
      solid[i] = false
      if RD(lx, ly) > 0 then
        kind[i] = K_ROAD
      else
        local nr = false
        for dy = -1, 1 do
          for dx = -1, 1 do
            if RD(lx + dx, ly + dy) > 0 then nr = true end
          end
        end
        kind[i] = nr and K_WALK or K_FREE
      end
    end
  end
  local function K(lx, ly) return kind[ly * CS + lx + 1] end
  local function wx(lx) return px0 + lx * TS + 8 end
  local function wy(ly) return py0 + ly * TS + 8 end
  local used = {}                       -- cells taken by a prop
  local function take(lx, ly) used[ly * CS + lx + 1] = true end
  local function freecell(lx, ly, k)
    return lx >= 0 and ly >= 0 and lx < CS and ly < CS and K(lx, ly) == (k or K_FREE)
           and not used[ly * CS + lx + 1]
  end

  ------------------------------------------------- buildings
  local function rect_free(x0, y0, w, h)
    if x0 < 0 or y0 < 0 or x0 + w > CS or y0 + h > CS then return false end
    for y = y0, y0 + h - 1 do
      for x = x0, x0 + w - 1 do
        if kind[y * CS + x + 1] ~= K_FREE then return false end
      end
    end
    return true
  end

  local function building(x0, y0, w, h, mat, roof, big)
    local cells = {}
    for y = y0, y0 + h - 1 do
      for x = x0, x0 + w - 1 do
        kind[y * CS + x + 1] = K_HOUSE
        solid[y * CS + x + 1] = true
      end
    end
    local function T(i, j, c) cells[j * w + i + 1] = c end
    local rows = h - 5
    local door = irange(r, 1, w - 2)
    local lit_p = big and 0.55 or 0.3
    for i = 0, w - 1 do
      local side = i == 0 and "l" or i == w - 1 and "r" or "m"
      local R = ROOF[roof]
      for j = 0, rows - 1 do
        local t
        if j == 0 then t = R.ridge[side]
        elseif j == rows - 1 then t = R.eaves[side]
        else t = (j % 2 == 1) and R.slope[side] or R.slope2[side] end
        T(i, j, t)
      end
      local fk
      if i == 0 then fk = "left"
      elseif i == w - 1 then fk = "right"
      elseif i == door then fk = r() < 0.5 and "door_lit" or "door"
      elseif r() < 0.15 and not big then fk = "plain"
      else
        local u, g = r() < lit_p, r() < lit_p
        fk = (u and g) and "win_ug" or u and "win_u" or g and "win_g" or "win"
      end
      local fc = FACADE[mat][fk]
      for j = 0, 4 do T(i, rows + j, fc[j + 1]) end
      local fx, fb = wx(x0 + i), py0 + (y0 + h) * TS
      if fk == "win_g" or fk == "win_ug" then add_light(ch, fx, fb - 20, 26, 3, 0, 0.7) end
      if fk == "door_lit" then add_light(ch, fx, fb - 6, 24, 3, 0, 0.7) end
    end
    local bottom = py0 + (y0 + h) * TS
    local o = { bld = cells, x = px0 + x0 * TS, y = bottom, top = py0 + y0 * TS, w = w, h = h, z = bottom }
    ch.objs[#ch.objs + 1] = o
    -- chimneys on the ridge, some smoking
    local n = big and 0 or irange(r, 0, 2)
    for k = 1, n do
      local i = irange(r, 0, w - 1)
      local c = add_obj(ch, r() < 0.5 and "chimney" or "chimney1", wx(x0 + i), py0 + y0 * TS + 14, bottom + 0.5)
      if r() < 0.45 then ch.smokes[#ch.smokes + 1] = { x = c.x, y = c.y - 30 } end
    end
    if big then
      add_obj(ch, "spire", px0 + (x0 + w / 2) * TS, py0 + (y0 + 1) * TS + 6, bottom + 0.5)
    end
  end

  local function place_buildings(big)
    if big then
      for yb = CS - 4, 7, -1 do
        for w = 11, 8, -1 do
          for x = 0, CS - w do
            if rect_free(x, yb - 7, w, 8) then
              building(x, yb - 7, w, 8, "dark", "lead", true)
              goto placed
            end
          end
        end
      end
      ::placed::
    end
    for yb = CS - 1, 6, -1 do
      local x = 0
      while x < CS do
        local h = r() < 0.55 and 7 or 8
        if yb - h + 1 >= 0 and rect_free(x, yb - h + 1, 3, h) then
          local w, wmax = 3, irange(r, 4, 7)
          while w < wmax and rect_free(x, yb - h + 1, w + 1, h) do w = w + 1 end
          building(x, yb - h + 1, w, h, pick(r, FMATS), pick(r, RMATS))
          x = x + w + (r() < 0.2 and 1 or 0)
        else
          x = x + 1
        end
      end
    end
  end

  ------------------------------------------------- districts
  local yard_props = { { "tree", 0.025, { 6, 3 } }, { "tree2", 0.02, { 5, 3 } }, { "bush", 0.05, { 9, 4 } },
    { "bush2", 0.04, { 8, 4 } }, { "barrel", 0.035, { 6, 3 } }, { "crates", 0.025, { 6, 3 } },
    { "crate", 0.03, { 6, 3 } }, { "well", 0.006, { 10, 5 } } }

  local function scatter(list, k, ground_cb)
    for ly = 0, CS - 1 do
      for lx = 0, CS - 1 do
        if freecell(lx, ly, k) then
          for _, p in ipairs(list) do
            if r() < p[2] then
              take(lx, ly)
              add_obj(ch, p[1], wx(lx) + irange(r, -3, 3), wy(ly) + irange(r, -2, 4), nil, p[3])
              break
            end
          end
        end
      end
    end
  end

  local kd = d.kind
  if kd == "town" or kd == "chapel" then
    place_buildings(kd == "chapel")
    for i = 1, CS * CS do if kind[i] == K_FREE then kind[i] = K_YARD end end
    scatter(yard_props, K_YARD)
  elseif kd == "cemetery" then
    for i = 1, CS * CS do if kind[i] == K_FREE then kind[i] = K_GRASS end end
    -- gravel paths across, then the fence along the street
    for ly = 0, CS - 1 do
      for lx = 0, CS - 1 do
        if K(lx, ly) == K_GRASS and (lx == 7 or lx == 8 or ly == 8) then kind[ly * CS + lx + 1] = K_PATH end
      end
    end
    -- a mausoleum
    if r() < 0.7 then
      for t = 1, 20 do
        local x, y = irange(r, 1, CS - 6), irange(r, 1, CS - 5)
        local ok = true
        for yy = y, y + 3 do for xx = x, x + 4 do if not freecell(xx, yy, K_GRASS) then ok = false end end end
        if ok then
          for yy = y, y + 3 do for xx = x, x + 4 do take(xx, yy); solid[yy * CS + xx + 1] = yy >= y + 1 end end
          add_obj(ch, "mausoleum", px0 + (x + 2.5) * TS, py0 + (y + 4) * TS - 2)
          add_light(ch, px0 + (x + 2.5) * TS, py0 + (y + 4) * TS + 4, 26, 3, 0.2)
          add_obj(ch, "candles2", px0 + (x + 1) * TS, py0 + (y + 4) * TS + 6)
          break
        end
      end
    end
    for ly = 1, CS - 2, 3 do
      for lx = 1, CS - 2, 2 do
        if freecell(lx, ly, K_GRASS) and r() < 0.8 then
          take(lx, ly)
          local g = pick(r, GRAVES)
          add_obj(ch, g, wx(lx), wy(ly) + 4, nil, { 7, 3 })
          if r() < 0.18 then
            add_obj(ch, r() < 0.5 and "candles" or "candles2", wx(lx) + 8, wy(ly) + 9)
            add_light(ch, wx(lx) + 8, wy(ly) + 6, 30, 4, 0.25, 0.8)
          end
        end
      end
    end
    for k = 1, irange(r, 1, 2) do
      local lx, ly = irange(r, 1, 14), irange(r, 1, 14)
      if freecell(lx, ly, K_GRASS) then take(lx, ly); add_obj(ch, "angel", wx(lx), wy(ly) + 6, nil, { 9, 5 }) end
    end
    scatter({ { "tree3", 0.03, { 5, 3 } }, { "tree", 0.02, { 6, 3 } }, { "bush2", 0.02, { 8, 4 } } }, K_GRASS)
    -- railings where the cemetery meets the pavement, a gap for the paths
    for ly = 0, CS - 1 do
      for lx = 0, CS - 1 do
        local k = K(lx, ly)
        if k == K_GRASS and not used[ly * CS + lx + 1] then
          local n = ly > 0 and K(lx, ly - 1) == K_WALK
          local s = ly < CS - 1 and K(lx, ly + 1) == K_WALK
          local w = lx > 0 and K(lx - 1, ly) == K_WALK
          local e = lx < CS - 1 and K(lx + 1, ly) == K_WALK
          if n or s then
            add_obj(ch, "fence_x", wx(lx), py0 + ly * TS + (n and 3 or 15), nil, { 9, 3 })
          elseif w or e then
            add_obj(ch, "fence_y", px0 + lx * TS + (w and 2 or 14), wy(ly) + 8, nil, { 3, 9 })
          end
        end
      end
    end
  elseif kd == "park" then
    for i = 1, CS * CS do if kind[i] == K_FREE then kind[i] = K_GRASS end end
    for ly = 0, CS - 1 do
      for lx = 0, CS - 1 do
        if K(lx, ly) == K_GRASS and ((lx >= 7 and lx <= 8) or (ly >= 7 and ly <= 8)) then
          kind[ly * CS + lx + 1] = K_PATH
        end
      end
    end
    local cxp, cyp = px0 + 8 * TS, py0 + 8 * TS
    if r() < 0.5 then
      add_obj(ch, "fountain", cxp, cyp + 12, nil, { 34, 10 })
    else
      add_obj(ch, "well", cxp, cyp + 8, nil, { 12, 5 })
    end
    for y = 6, 9 do for x = 5, 10 do take(x, y) end end
    for _, p in ipairs({ { 7, 4 }, { 9, 11 } }) do
      if freecell(p[1], p[2], K_PATH) then take(p[1], p[2]); ch.lampspots[#ch.lampspots + 1] = p end
    end
    scatter({ { "tree", 0.05, { 6, 3 } }, { "tree2", 0.04, { 5, 3 } }, { "tree3", 0.03, { 5, 3 } },
              { "bush", 0.07, { 9, 4 } }, { "bush2", 0.06, { 8, 4 } } }, K_GRASS)
    scatter({ { "bench", 0.06, { 12, 3 } } }, K_PATH)
  elseif kd == "square" or kd == "pyre" or kd == "chapel" then
    -- (the chapel's front is the marble square; see the buildings above)
  end
  if kd == "square" then
    local cxp, cyp = px0 + 8 * TS, py0 + 8 * TS
    if r() < 0.6 or (cx == 0 and cy == 0) then
      add_obj(ch, "fountain", cxp, cyp + 12, nil, { 34, 10 })
    else
      add_obj(ch, "angel", cxp, cyp + 8, nil, { 10, 5 })
    end
    local first = irange(r, 0, 1)
    for k = first, 3, 2 do
      local a = k * PI / 2 + PI / 4
      local bx, by = cxp + cos(a) * 62, cyp + sin(a) * 50 + 10
      if road_at((fdiv(bx, TS)), (fdiv(by, TS)), ne) > 0 then
        add_obj(ch, "brazier", bx, by, nil, { 8, 4 })
        ch.fires[#ch.fires + 1] = { x = bx, y = by - 25, w = 7, rate = 1.2, big = false }
        add_light(ch, bx, by - 8, 62, 6, 1.0)
      end
    end
    if r() < 0.5 then add_obj(ch, "bench", cxp - 48, cyp - 40, nil, { 12, 3 }) end
  elseif kd == "pyre" then
    local cxp, cyp = px0 + 8 * TS, py0 + 8 * TS
    add_obj(ch, "pyre", cxp, cyp + 14, nil, { 16, 7 })
    ch.fires[#ch.fires + 1] = { x = cxp, y = cyp + 4, w = 14, rate = 4.0, big = true }
    add_light(ch, cxp, cyp + 4, 112, 7, 1.0, 0.6)
    add_light(ch, cxp, cyp, 72, 7, 1.0, 0.3)
    local spots = {}
    for k = 1, 10 do
      local a = r() * 2 * PI
      local dd = 50 + r() * 22
      local ox, oy = cxp + cos(a) * dd, cyp + 14 + sin(a) * dd * 0.7
      local ok = road_at(fdiv(ox, TS), fdiv(oy, TS), ne) > 0 and #spots < 6
      for _, q in ipairs(spots) do
        if abs(q[1] - ox) < 40 and abs(q[2] - oy) < 22 then ok = false end
      end
      if ok then
        spots[#spots + 1] = { ox, oy }
        local name = pick(r, { "coffin", "coffin", "coffin_up", "cage", "barrel" })
        add_obj(ch, name, ox, oy, nil, name == "coffin" and { 14, 4 } or { 8, 4 })
      end
    end
  elseif kd == "chapel" then
    for k = -1, 1, 2 do
      local bx, by = px0 + (8 + k * 3.6) * TS, py0 + 13.6 * TS
      if road_at(fdiv(bx, TS), fdiv(by, TS), ne) > 0 then
        add_obj(ch, "brazier", bx, by, nil, { 8, 4 })
        ch.fires[#ch.fires + 1] = { x = bx, y = by - 25, w = 7, rate = 1.2 }
        add_light(ch, bx, by - 8, 60, 6, 1.0)
      end
    end
    local ax, ay = px0 + 8 * TS, py0 + 13.2 * TS
    if road_at(fdiv(ax, TS), fdiv(ay, TS), ne) > 0 then add_obj(ch, "angel", ax, ay + 8, nil, { 9, 5 }) end
  end

  ------------------------------------------------- street furniture
  -- gas lamps along the pavements, some of them dark
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      if K(lx, ly) == K_WALK and not used[ly * CS + lx + 1] and h01(tx0 + lx, ty0 + ly, 31) < 0.08 then
        ch.lampspots[#ch.lampspots + 1] = { lx, ly }
      end
    end
  end
  local placed = {}
  for _, p in ipairs(ch.lampspots) do
    local ok = true
    for _, q in ipairs(placed) do
      if abs(q[1] - p[1]) + abs(q[2] - p[2]) < 8 then ok = false end
    end
    if ok then
      placed[#placed + 1] = p
      take(p[1], p[2])
      local x, y = wx(p[1]), wy(p[2]) + 4
      local key = key2(tx0 + p[1], ty0 + p[2])
      local o = add_obj(ch, "lamp", x, y, nil, { 4, 2 })
      o.lamp = key
      if lamp_state[key] == nil then lamp_state[key] = h01(tx0 + p[1], ty0 + p[2], 33) < 0.72 end
      ch.lamps[#ch.lamps + 1] = { x = x, y = y, key = key }
    end
  end
  -- odds and ends on the pavements and in the street
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      if freecell(lx, ly, K_WALK) then
        local v = r()
        local below = ly > 0 and K(lx, ly - 1) == K_HOUSE
        if v < 0.03 and below then
          take(lx, ly); add_obj(ch, pick(r, { "barrel", "crate", "crates" }), wx(lx), wy(ly), nil, { 6, 3 })
        elseif v < 0.037 then
          take(lx, ly); add_obj(ch, "bollard", wx(lx), wy(ly) + 4, nil, { 3, 2 })
        elseif v < 0.055 then
          take(lx, ly); add_obj(ch, "coffin_up", wx(lx), wy(ly), nil, { 7, 3 })
        end
      end
    end
  end
  if kd == "town" and r() < 0.22 then
    -- an abandoned carriage, where the street is wide enough
    for t = 1, 30 do
      local lx, ly = irange(r, 0, CS - 4), irange(r, 1, CS - 2)
      local ok = true
      for yy = ly - 1, ly + 1 do for xx = lx, lx + 3 do if not freecell(xx, yy, K_ROAD) then ok = false end end end
      if ok then
        for yy = ly - 1, ly + 1 do for xx = lx, lx + 3 do take(xx, yy) end end
        add_obj(ch, "carriage", px0 + (lx + 1.6) * TS, wy(ly) + 4, nil, { 34, 6 })
        break
      end
    end
  end
  if kd == "town" and r() < 0.25 then
    for t = 1, 12 do
      local lx, ly = irange(r, 0, CS - 1), irange(r, 0, CS - 1)
      if freecell(lx, ly, K_ROAD) then take(lx, ly); add_obj(ch, "coffin", wx(lx), wy(ly) + 4, nil, { 14, 4 }); break end
    end
  end

  ------------------------------------------------- the ground, overlays
  local G = GROUND
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      local i = ly * CS + lx + 1
      local k = kind[i]
      local tx, ty = tx0 + lx, ty0 + ly
      local hv = hash(tx, ty, 21)
      if k == K_ROAD then
        local pv = RD(lx, ly)
        local set = pv == PV_SETTS and G.setts or pv == PV_FLAGS and G.flags or pv == PV_ALLEY and G.cobble_moss
          or pv == PV_WARM and G.cobble_warm or pv == PV_MARBLE and G.marble or pv == PV_DARK and G.flags_dark
          or pv == PV_WET and G.cobble_wet or G.cobble
        A[i] = set[hv % #set + 1]
        -- the kerb where the street meets the pavement
        local m = 0
        if RD(lx, ly - 1) == 0 then m = m | 1 end
        if RD(lx + 1, ly) == 0 then m = m | 2 end
        if RD(lx, ly + 1) == 0 then m = m | 4 end
        if RD(lx - 1, ly) == 0 then m = m | 8 end
        if m > 0 and pv ~= PV_MARBLE then
          B[i] = CURB[m]
        elseif (hv >> 8) % 100 < 9 then
          local dv = (hv >> 16) % 100
          local set2 = dv < 30 and DECAL.puddle or dv < 48 and DECAL.leaves or dv < 62 and DECAL.crack
            or dv < 72 and DECAL.drain or dv < 78 and DECAL.manhole or dv < 88 and DECAL.blood
            or dv < 95 and DECAL.straw or DECAL.bones
          B[i] = set2[(hv >> 24) % #set2 + 1]
        end
      elseif k == K_WALK then
        A[i] = G.pave[hv % #G.pave + 1]
        if (hv >> 8) % 100 < 6 then
          local set2 = ((hv >> 16) % 2 == 0) and DECAL.leaves or DECAL.crack
          B[i] = set2[(hv >> 24) % #set2 + 1]
        end
      elseif k == K_HOUSE then
        A[i] = G.dirt[1]                   -- never seen: the house is drawn over it
      elseif k == K_GRASS then
        local set = kd == "cemetery" and G.grass_dark or G.grass
        A[i] = set[hv % #set + 1]
      elseif k == K_PATH then
        A[i] = G.gravel[hv % #G.gravel + 1]
      else   -- yards: grass, earth and gravel in patches
        local n = sin(tx * 0.9 + ty * 0.4) + sin(ty * 1.1 - tx * 0.3) + ((hv % 100) / 100 - 0.5)
        if n > 0.5 then A[i] = G.grass[hv % #G.grass + 1]; kind[i] = K_GRASS
        elseif n > -0.6 then A[i] = G.dirt[hv % #G.dirt + 1]
        else A[i] = G.gravel[hv % #G.gravel + 1] end
      end
    end
  end
  -- grass spilling over its neighbours (inside the chunk)
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      local i = ly * CS + lx + 1
      local k = kind[i]
      if k ~= K_GRASS and k ~= K_HOUSE and not B[i] then
        local m = 0
        if ly > 0 and K(lx, ly - 1) == K_GRASS then m = m | 1 end
        if lx < CS - 1 and K(lx + 1, ly) == K_GRASS then m = m | 2 end
        if ly < CS - 1 and K(lx, ly + 1) == K_GRASS then m = m | 4 end
        if lx > 0 and K(lx - 1, ly) == K_GRASS then m = m | 8 end
        if m > 0 then B[i] = GRASS_EDGE[m] end
      end
    end
  end

  -- into the map (layer 1: cells 0-127, layer 2: 128-255)
  local rx0, ry0 = (cx % RING) * CS * 2, (cy % RING) * CS * 2
  for ly = 0, CS - 1 do
    local my = ry0 + ly * 2
    for lx = 0, CS - 1 do
      local i = ly * CS + lx + 1
      local mx = rx0 + lx * 2
      local a, b = A[i] or G.cobble[1], B[i] or 0
      mset(mx, my, a); mset(mx + 1, my, a + 1); mset(mx, my + 1, a + SW8); mset(mx + 1, my + 1, a + SW8 + 1)
      if b > 0 then
        mset(128 + mx, my, b); mset(129 + mx, my, b + 1); mset(128 + mx, my + 1, b + SW8)
        mset(129 + mx, my + 1, b + SW8 + 1)
      else
        mset(128 + mx, my, 0); mset(129 + mx, my, 0); mset(128 + mx, my + 1, 0); mset(129 + mx, my + 1, 0)
      end
    end
  end
  ch.ready = true
end

local function new_chunk(cx, cy)
  local k = key2(cx, cy)
  local sk = (cy % RING) * RING + (cx % RING)
  local old = slots[sk]
  if old and old ~= k then chunks[old] = nil end
  slots[sk] = k
  local ch = { cx = cx, cy = cy, ready = false, objs = {}, cols = {}, lights = {}, fires = {}, smokes = {},
               lamps = {}, lampspots = {} }
  chunks[k] = ch
  return ch
end

local function chunk(cx, cy) return chunks[key2(cx, cy)] end

-- one chunk at a time is made in the background, a slice per frame
local job, job_ch
local gen_frames = 0

local function finish_job()
  while job and coroutine.status(job) ~= "dead" do
    local ok, err = coroutine.resume(job)
    if not ok then error(err) end
  end
  job, job_ch = nil, nil
end

local function ensure(cx, cy)
  local ch = chunk(cx, cy)
  if ch and ch.ready then return ch end
  if job_ch and job_ch.cx == cx and job_ch.cy == cy then
    finish_job()
    return job_ch or chunk(cx, cy)
  end
  ch = new_chunk(cx, cy)
  gen(ch)
  return ch
end

local cam_x, cam_y = 0, 0

local function stream()
  -- what is on screen has to be there now
  for cy = fdiv(cam_y, CPX), fdiv(cam_y + H - 1, CPX) do
    for cx = fdiv(cam_x, CPX), fdiv(cam_x + W - 1, CPX) do ensure(cx, cy) end
  end
  if job then
    local ok, err = coroutine.resume(job)
    if not ok then error(err) end
    gen_frames = gen_frames + 1
    if coroutine.status(job) == "dead" then job, job_ch = nil, nil end
    return
  end
  -- the next one around the view, nearest first
  local best, bd
  local mx, my = cam_x + W / 2, cam_y + H / 2
  for cy = fdiv(cam_y - MARGIN, CPX), fdiv(cam_y + H + MARGIN, CPX) do
    for cx = fdiv(cam_x - MARGIN, CPX), fdiv(cam_x + W + MARGIN, CPX) do
      local ch = chunk(cx, cy)
      if not (ch and ch.ready) then
        local dx, dy = (cx + 0.5) * CPX - mx, (cy + 0.5) * CPX - my
        local dd = dx * dx + dy * dy
        if not bd or dd < bd then best, bd = { cx, cy }, dd end
      end
    end
  end
  if best then
    job_ch = new_chunk(best[1], best[2])
    job = coroutine.create(gen)
    timeslice(job, 40)
    local ok, err = coroutine.resume(job, job_ch)
    if not ok then error(err) end
    if coroutine.status(job) == "dead" then job, job_ch = nil, nil end
  end
end

----------------------------------------------------------------- the hunter

local DIRS = { [-1] = { [-1] = 5, [0] = 4, [1] = 3 }, [0] = { [-1] = 6, [0] = 0, [1] = 2 },
               [1] = { [-1] = 7, [0] = 0, [1] = 1 } }          -- [dy][dx]: S SE E NE N NW W SW
local DIRV = { { 0, 1 }, { 0.7071, 0.7071 }, { 1, 0 }, { 0.7071, -0.7071 }, { 0, -1 }, { -0.7071, -0.7071 },
               { -1, 0 }, { -0.7071, 0.7071 } }                 -- the same, as steps on the screen
local HP_MAX = 10
-- the hunter: where, which way, the animation playing (HUNT[anim], frame f,
-- ticks ft, played backwards when rev), the action under way (nil: free to
-- walk), the saw cleaver out (ext), health, invulnerable ticks
local ST_MAX = 100
-- rally: health just lost, won back by striking soon (it fades in a while);
-- st: stamina (st_wait: ticks before it comes back); lock: the creature the
-- hunter keeps facing; bt: ticks B is held (a tap dodges, holding runs)
local P = { x = 0, y = 0, dir = 0, anim = "idle", f = 1, ft = 0, rev = false, act = nil, ext = false,
            hp = HP_MAX, inv = 0, combo = 0, queued = false, moving = false, hits = {}, trail = {},
            rally = 0, rally_t = 0, st = ST_MAX, st_wait = 0, lock = nil, bt = 0, brel = 0, l1 = false,
            r1 = false, charge = 0, charged = false }

local function solid_at(x, y)
  local tx, ty = fdiv(x, TS), fdiv(y, TS)
  local ch = chunk(tx // CS, ty // CS)
  if not (ch and ch.ready) then return true end
  return ch.solid[(ty % CS) * CS + (tx % CS) + 1]
end

local function blocked(x, y)
  if solid_at(x - 6, y - 3) or solid_at(x + 6, y - 3) or solid_at(x - 6, y + 2) or solid_at(x + 6, y + 2) then
    return true
  end
  -- posts, fountains, graves: of this chunk, and of a neighbour only near its
  -- border (none is wider than 48 pixels)
  local pcx, pcy = fdiv(x, CPX), fdiv(y, CPX)
  local fx, fy = x - pcx * CPX, y - pcy * CPX
  for cy = fy < 48 and pcy - 1 or pcy, fy > CPX - 48 and pcy + 1 or pcy do
    for cx = fx < 48 and pcx - 1 or pcx, fx > CPX - 48 and pcx + 1 or pcx do
      local ch = chunk(cx, cy)
      if ch and ch.ready then
        for _, c in ipairs(ch.cols) do
          local dx = x - c.x
          if dx < 48 and dx > -48 then
            dx = dx / (c.rx + 5)
            local dy = (y - c.y) / (c.ry + 3)
            if dx * dx + dy * dy < 1 then return true end
          end
        end
      end
    end
  end
  return false
end

-- the free spot of a street nearest to the middle of the screen
local function start_here()
  local mx, my = cam_x + W / 2, cam_y + H * 0.62
  for rad = 0, 12 do
    for dy = -rad, rad do
      for dx = -rad, rad do
        if abs(dx) == rad or abs(dy) == rad then
          local x, y = (fdiv(mx, TS) + dx) * TS + 8, (fdiv(my, TS) + dy) * TS + 8
          local tx, ty = fdiv(x, TS), fdiv(y, TS)
          local ch = chunk(tx // CS, ty // CS)
          if ch and ch.ready and ch.kind[(ty % CS) * CS + tx % CS + 1] == K_ROAD and not blocked(x, y) then
            P.x, P.y = x, y
            return
          end
        end
      end
    end
  end
end

local function place_player()
  -- the start: on a street of the first square, south of its fountain
  ensure(0, 0)
  for rad = 0, 10 do
    for dy = -rad, rad do
      for dx = -rad, rad do
        local x, y = (8 + dx) * TS + 8, (12 + dy) * TS + 8
        if not blocked(x, y) then P.x, P.y = x, y; return end
      end
    end
  end
  P.x, P.y = 8 * TS + 8, 12 * TS + 8
end


----------------------------------------------------------------- particles

local parts = {}
local MAXP = 200
local FLAME = { 0xF8F8D8, 0xF8E890, 0xF8C050, 0xF89030, 0xE06020, 0xA83818, 0x602010 }

local function spawn(x, y, vx, vy, life, kind)
  if #parts >= MAXP then return end
  parts[#parts + 1] = { x = x, y = y, vx = vx, vy = vy, t = 0, life = life, kind = kind }
end

-- a little wind for flames and embers: noise looked up, not drawn every time
local JIT = { k = 0 }
for i = 0, 63 do JIT[i] = (((i * 37 + 11) * 73) % 101 / 100 - 0.5) end

local function update_parts()
  local n = #parts
  local i = 1
  JIT.k = (JIT.k + 13) & 63
  local k0 = JIT.k
  while i <= n do
    local p = parts[i]
    local pt = p.t + 1
    p.t = pt
    if pt >= p.life then
      parts[i] = parts[n]
      parts[n] = nil
      n = n - 1
    else
      p.x = p.x + p.vx
      p.y = p.y + p.vy
      local k = p.kind
      if k == 1 then
        p.vx = p.vx * 0.94 + JIT[(k0 + i * 7) & 63] * 0.12
        p.vy = p.vy * 0.985 - 0.012
      elseif k == 2 then
        p.vx = p.vx + JIT[(k0 + i * 5) & 63] * 0.08
        p.vy = p.vy * 0.995 - 0.004
      elseif k == 3 then
        p.vx = p.vx * 0.99 + 0.004
        p.vy = p.vy * 0.995
      else
        p.vy = p.vy + 0.03
      end
      i = i + 1
    end
  end
end

----------------------------------------------------------------- sound

local function sfx_step() note(0, 70 + math.random(30), 45, NOISE, 22) end
local function sfx_light()
  note(1, 523, 120, TRIANGLE, 70); note(2, 784, 400, TRIANGLE, 50); note(3, 2400, 300, NOISE, 25)
end
local bell_t, wind_t, crackle_t = 240, 60, 0
local CHORDS = { { 110, 131, 165 }, { 98, 117, 147 }, { 87, 110, 131 }, { 82, 104, 123 } }
local chord_i, chord_t = 0, 0

local function update_sound(fire_near)
  bell_t = bell_t - 1
  if bell_t <= 0 then
    bell_t = 1500 + math.random(900)
    note(7, 196, 3200, METAL, 30)
    note(6, 98, 3600, SINE, 34)
  end
  wind_t = wind_t - 1
  if wind_t <= 0 then
    wind_t = 200 + math.random(260)
    note(5, 300 + math.random(200), 2600, NOISE, 9)
  end
  chord_t = chord_t - 1
  if chord_t <= 0 then
    chord_i = chord_i % #CHORDS + 1
    chord_t = 300
    local c = CHORDS[chord_i]
    note(4, c[1], 5200, TRIANGLE, 22)
    note(3, c[2 + chord_i % 2], 5000, SINE, 14)
  end
  if fire_near and fire_near < 140 then
    crackle_t = crackle_t - 1
    if crackle_t <= 0 then
      crackle_t = 3 + math.random(14)
      note(2, 1400 + math.random(2400), 25 + math.random(30), NOISE, floor(60 * (1 - fire_near / 140)))
    end
  end
end

----------------------------------------------------------------- the frame


local state = "title"
local t = 0
local banner, banner_t, here = nil, 0, nil
local near_lamp

local function lamp_at(key) return lamp_state[key] end

local function play(name, rev)
  local a = HUNT[name]
  P.anim, P.rev, P.ft, P.newf = name, rev or false, 0, true
  P.f = rev and #a.t or 1
end

-- one tick of the animation (rate: ticks per tick); true when a one-shot
-- animation has just ended (it stays on its last frame)
local function step_anim(rate)
  local a = HUNT[P.anim]
  P.newf = false
  P.ft = P.ft + (rate or 1)
  if P.ft >= a.t[P.f] then
    if P.rev then
      if P.f > 1 then P.f, P.ft, P.newf = P.f - 1, 0, true else return true end
    elseif P.f < #a.t then P.f, P.ft, P.newf = P.f + 1, 0, true
    elseif a.loop then P.f, P.ft, P.newf = 1, 0, true
    else return true end                    -- ended: it stays so
  end
  return false
end

local function xname(n) return P.ext and n .. "_x" or n end

-- moves the hunter by (vx, vy), sliding round posts and corners
local function walk_by(vx, vy)
  local nx, ny = P.x + vx, P.y + vy
  local mx, my = false, false
  if not blocked(nx, P.y) then P.x, mx = nx, true end
  if not blocked(P.x, ny) then P.y, my = ny, true end
  local sp = max(abs(vx), abs(vy))
  if vx ~= 0 and not mx and abs(vy) < 0.01 then
    for _, o in ipairs({ -1, 1 }) do
      if not blocked(nx, P.y + o * sp) then P.x, P.y = nx, P.y + o * sp; return end
    end
  elseif vy ~= 0 and not my and abs(vx) < 0.01 then
    for _, o in ipairs({ -1, 1 }) do
      if not blocked(P.x + o * sp, ny) then P.x, P.y = P.x + o * sp, ny; return end
    end
  end
end

local function forward(d)
  local v = DIRV[P.dir + 1]
  walk_by(v[1] * d, v[2] * d)
end

----------------------------------------------------------------- what the hunter does

local function sfx_swing(heavy)
  note(1, heavy and 900 or 1500, heavy and 160 or 110, NOISE, heavy and 70 or 55)
  note(2, heavy and 60 or 90, 120, SAW, 40)
end
local function sfx_shot()
  note(0, 700, 220, NOISE, 200); note(1, 55, 260, SQUARE, 150); note(2, 2600, 90, METAL, 60)
end
local function sfx_clank() note(1, 1800, 160, METAL, 90); note(2, 300, 90, SQUARE, 50) end
local function sfx_hurt() note(1, 110, 260, SAW, 120); note(2, 400, 120, NOISE, 90) end
local function sfx_fall() note(0, 50, 300, NOISE, 160); note(1, 70, 200, SQUARE, 90) end

-- the creatures of the night (filled further down)
local FOE = { list = {}, shots = {}, rings = {}, burns = {}, slain = {}, boss = nil, shake = 0, killed = 0,
              respawns = 0, won = nil, won_t = 0 }
local flash, tracer = 0, nil
local died_t = 0

-- with no direction held, a blow or a shot turns to the target (or the
-- nearest creature)
local function aim_at(range)
  local o = P.lock or FOE.nearest(range)
  if o then P.dir = FOE.dir_to(o.x - P.x, o.y - P.y) end
end

-- stamina: every blow and dodge costs some; it comes back after a pause
local function spend(n)
  P.st, P.st_wait = max(-20, P.st - n), 30
end

-- the rally: blood taken back from what the blade cuts
local function rally(n)
  local back = min(n, P.rally)
  if back > 0 and P.act ~= "dead" then P.hp, P.rally = min(HP_MAX, P.hp + back), P.rally - back end
end

local function attack(stage, dx, dy)
  if dx ~= 0 or dy ~= 0 then P.dir = DIRS[dy][dx] else aim_at(44) end
  spend(P.ext and 20 or 15)
  P.act, P.combo, P.queued = "attack", stage, false
  P.trail = {}
  play((P.ext and "xslash" or "slash") .. stage)
end

-- the heavy blow: held at the top while R1 is held, it charges
local function heavy(dx, dy)
  if dx ~= 0 or dy ~= 0 then P.dir = DIRS[dy][dx] else aim_at(44) end
  spend(26)
  P.act, P.charge, P.charged, P.queued = "heavy", 0, false, false
  P.trail = {}
  play(xname("heavy"))
end

-- the trick: the saw cleaver transformed in a blow, the combo goes on
local function trick()
  spend(18)
  P.act, P.combo, P.queued = "trick", min(P.combo + 1, 3), false
  P.trail = {}
  play(P.ext and "trick_x" or "trick")
end

local function sfx_dodge() note(0, 400, 90, NOISE, 50); note(1, 900, 60, NOISE, 30) end

-- B tapped: with a target, a quickstep that way (back: the backstep);
-- without one, a roll; standing still, the backstep
local function dodge(dx, dy)
  spend(P.lock and 15 or 18)
  sfx_dodge()
  local k
  if dx ~= 0 or dy ~= 0 then
    local di = DIRS[dy][dx]
    if P.lock then
      local rel = (di - P.dir) % 8
      k = (rel <= 1 or rel == 7) and "f" or rel == 2 and "l" or rel == 6 and "r" or nil
      if k then
        P.act, P.inv, P.dv = "qstep", 12, DIRV[di + 1]
        play(xname("qstep_" .. k))
        return
      end
    else
      P.dir = di
      P.act, P.inv, P.dv = "roll", 16, DIRV[di + 1]
      play(xname("roll"))
      return
    end
  end
  P.act, P.inv = "backstep", 22
  play(xname("backstep"))
end

-- the visceral attack on a staggered creature
local function visceral(o)
  P.dir = FOE.dir_to(o.x - P.x, o.y - P.y)
  P.act, P.vic, P.inv = "visceral", o, 90
  o.act = "held"
  play(xname("visceral"))
end

local function shoot()
  aim_at(130)
  P.act = "shoot"
  play(xname("shoot"))
end

-- the shot: a flash at the muzzle, a light, a trail to the first wall
local function fire()
  local fr = HUNT[P.anim].d[P.dir + 1][P.f]
  local mx, my = P.x + fr[9], P.y + fr[10]
  local v = DIRV[P.dir + 1]
  local x, y = mx, my
  for k = 1, 60 do
    x, y = x + v[1] * 4, y + v[2] * 4
    if solid_at(x, y + 18) then break end
  end
  local hx, hy = FOE.shot(mx, my, x, y)
  if hx then x, y = hx, hy end
  flash, tracer = 6, { mx, my, x, y, 6 }
  sfx_shot()
  for k = 1, 10 do
    spawn(x, y, (math.random() - 0.5) * 2, (math.random() - 0.5) * 2 - 0.5, 10 + math.random(10), 4)
  end
  spawn(mx, my, v[1] * 0.3, -0.3, 60, 3)
end

-- burnt, struck: hurt (three ways), knocked down, or killed
local function hurt(amount, heavy)
  if P.inv > 0 or P.act == "dead" or P.act == "down" or P.act == "lying" or P.act == "getup" then return end
  P.rally, P.rally_t = min(P.rally + min(amount, P.hp), HP_MAX), 150
  P.hp = P.hp - amount
  sfx_hurt()
  local now = t
  local recent = 0
  P.hits[#P.hits + 1] = now
  for _, h in ipairs(P.hits) do if now - h < 200 then recent = recent + 1 end end
  if P.hp <= 0 then
    P.hp, P.act, died_t = 0, "dead", 0
    play(xname("death"))
  elseif heavy or recent >= 3 then
    P.hits = {}
    P.act, P.inv = "down", 0
    play(xname("down"))
  else
    P.act, P.inv = "hurt", 50
    play(xname("hurt" .. math.random(3)))
  end
end

----------------------------------------------------------------- the creatures of the night

-- The creatures (FOES, drawn by mkassets.py in 5 directions: SW W NW are SE
-- E NE mirrored) come out of the streets as the town is made around the
-- hunter, a few in every chunk, the kind depending on the district; four
-- bosses wait in the districts of their kind (a pyre, gardens, a cemetery,
-- a chapel). Everything here lives in FOE, so the main chunk keeps few locals.
do
  local list, shots, rings, burns = FOE.list, FOE.shots, FOE.rings, FOE.burns
  local BYNAME = {}
  for _, f in ipairs(FOES) do BYNAME[f.name] = f end
  FOE.byname = BYNAME
  -- how each one fights: hit points, speed, reach of its blows, damage, how
  -- far it sees, its size; heavy blows knock the hunter down
  local STATS = {
    pitchfork = { hp = 5, sp = 0.55, reach = 30, dmg = 2, sight = 110, r = 7 },
    torch = { hp = 5, sp = 0.6, reach = 22, dmg = 2, sight = 120, r = 7, torch = true },
    rifle = { hp = 4, sp = 0.5, reach = 130, dmg = 2, sight = 150, r = 7, ranged = true },
    crone = { hp = 4, sp = 0.55, reach = 18, dmg = 1, sight = 90, r = 6 },
    dog = { hp = 3, sp = 1.35, reach = 24, dmg = 1, sight = 140, r = 8 },
    scourge = { hp = 10, sp = 1.0, reach = 26, dmg = 3, sight = 130, r = 10, heavy = true },
    axehunter = { hp = 8, sp = 0.85, reach = 30, dmg = 2, sight = 140, r = 7 },
    church = { hp = 8, sp = 0.85, reach = 32, dmg = 2, sight = 140, r = 7 },
    kin = { hp = 3, sp = 0.5, reach = 14, dmg = 1, sight = 80, r = 5 },
    brainsucker = { hp = 6, sp = 0.5, reach = 22, dmg = 2, sight = 100, r = 7 },
    lantern = { hp = 5, sp = 0.4, reach = 24, dmg = 2, sight = 90, r = 7, lantern = true },
    spider = { hp = 6, sp = 0.9, reach = 30, dmg = 2, sight = 110, r = 12 },
    butcher = { hp = 60, sp = 0.6, reach = 40, dmg = 3, sight = 160, r = 14 },
    hound = { hp = 50, sp = 1.1, reach = 42, dmg = 3, sight = 170, r = 18 },
    father = { hp = 55, sp = 0.85, reach = 34, dmg = 3, sight = 170, r = 9 },
    watcher = { hp = 65, sp = 0.6, reach = 44, dmg = 3, sight = 180, r = 14 },
  }
  FOE.stats = STATS
  -- who lives where, and the boss of each kind of district
  local POOL = {
    town = { "pitchfork", "torch", "rifle", "crone", "pitchfork", "torch", "dog" },
    square = { "pitchfork", "torch", "crone", "rifle" },
    pyre = { "torch", "torch", "pitchfork", "crone" },
    park = { "dog", "dog", "scourge" },
    cemetery = { "axehunter", "church", "lantern", "dog" },
    chapel = { "kin", "brainsucker", "lantern", "spider", "church", "kin" },
  }
  local BOSS_OF = { pyre = "butcher", park = "hound", cemetery = "father", chapel = "watcher" }
  FOE.boss_of = BOSS_OF
  local MAXF = 14

  local function dir_to(dx, dy)
    return (2 - floor(math.atan(dy, dx) / (PI / 4) + 0.5)) % 8
  end
  FOE.dir_to = dir_to

  -- the frame on screen: the drawn direction, mirrored for SW W NW
  local function frame(o)
    local d = o.dir
    return o.def.a[o.anim].d[d <= 4 and d + 1 or 9 - d][o.f], d > 4
  end
  FOE.frame = frame
  local function point(o, k)
    local fr, flip = frame(o)
    local px, py = fr[5 + 2 * k], fr[6 + 2 * k]
    return o.x + (flip and -px or px), o.y + py
  end
  FOE.point = point

  local function play(o, name)
    o.anim, o.f, o.ft, o.newf = name, 1, 0, true
  end
  FOE.play = play
  -- one tick (rate ticks); true when a one-shot animation has ended
  local function step(o, rate)
    local a = o.def.a[o.anim]
    o.newf = false
    o.ft = o.ft + (rate or 1)
    if o.ft >= a.t[o.f] then
      if o.f < #a.t then o.f, o.ft, o.newf = o.f + 1, 0, true
      elseif a.loop then o.f, o.ft, o.newf = 1, 0, true
      else return true end
    end
    return false
  end
  FOE.step = step
  local function has(list_, f)
    if not list_ then return false end
    for _, v in ipairs(list_) do if v == f then return true end end
    return false
  end

  local function new(name, x, y, home)
    local def = BYNAME[name]
    local st = STATS[name]
    local o = { def = def, st = st, name = name, x = x, y = y, dir = 0, hp = st.hp, cd = 30 + math.random(60),
                boss = def.boss, home = home, hx = x, hy = y, alert = false, corpse = 0, z = y }
    play(o, "idle")
    o.f = math.random(#def.a.idle.t)
    list[#list + 1] = o
    return o
  end
  FOE.new = new

  -- the foot of a creature on the street: walls, houses and posts stop it
  local function stuck(x, y, r)
    local q = min(r, 8) * 0.6
    local tx0, tx1, ty0, ty1 = fdiv(x - q, TS), fdiv(x + q, TS), fdiv(y - 2, TS), fdiv(y + 2, TS)
    local ch
    for ty = ty0, ty1 do
      for tx = tx0, tx1 do
        ch = chunk(tx // CS, ty // CS)
        if not (ch and ch.ready) or ch.solid[(ty % CS) * CS + tx % CS + 1] then return true end
      end
    end
    for _, c in ipairs(ch.cols) do
      local dx = x - c.x
      if dx < 24 and dx > -24 then
        dx = dx / (c.rx + 3)
        local dy = (y - c.y) / (c.ry + 2)
        if dx * dx + dy * dy < 1 then return true end
      end
    end
    return false
  end
  local function move(o, vx, vy)
    local r = o.st.r
    local nx, ny = o.x + vx, o.y + vy
    if not stuck(nx, ny, r) then
      o.x, o.y = nx, ny
    elseif not stuck(nx, o.y, r) then
      o.x = nx
    elseif not stuck(o.x, ny, r) then
      o.y = ny
    end
  end

  -- a chunk made off screen gets its creatures (once; again after a death)
  local function populate(ch)
    ch.spawned = true
    local cx, cy = ch.cx, ch.cy
    if abs(cx) + abs(cy) <= 1 then return end         -- the first streets are quiet
    local d = district(cx, cy)
    local r = newrng(hash(cx, cy, 23 + FOE.respawns))
    local pool = POOL[d.kind] or POOL.town
    local n = d.kind == "town" and irange(r, 0, 2) or irange(r, 1, 3)
    local function spot()
      for _ = 1, 16 do
        local lx, ly = irange(r, 1, CS - 2), irange(r, 1, CS - 2)
        local k = ch.kind[ly * CS + lx + 1]
        local x, y = (cx * CS + lx) * TS + 8, (cy * CS + ly) * TS + 8
        if (k == K_ROAD or k == K_WALK or k == K_FREE) and not ch.solid[ly * CS + lx + 1] and not stuck(x, y, 8) then
          return x, y
        end
      end
    end
    for _ = 1, n do
      if #list >= MAXF then break end
      local x, y = spot()
      if x then new(pick(r, pool), x, y, key2(cx, cy)) end
    end
    -- a boss, in some districts of its kind, until it is slain
    local bn = BOSS_OF[d.kind]
    local key = key2(cx, cy)
    if bn and not FOE.slain[key] and abs(cx) + abs(cy) > 2 and hash(cx, cy, 29) % 100 < 60 then
      for _, o in ipairs(list) do if o.boss and o.home == key then return end end
      local x, y
      for rad = 0, 5 do
        for _ = 1, 8 do
          local lx, ly = 8 + irange(r, -rad, rad), 8 + irange(r, -rad, rad)
          local k = ch.kind[ly * CS + lx + 1]
          local px, py = (cx * CS + lx) * TS + 8, (cy * CS + ly) * TS + 8
          if k ~= K_HOUSE and not ch.solid[ly * CS + lx + 1] and not stuck(px, py, 12) then x, y = px, py; break end
        end
        if x then break end
      end
      if x then new(bn, x, y, key) end
    end
  end
  FOE.populate = populate

  local function on_screen_chunk(ch)
    local x0, y0 = ch.cx * CPX, ch.cy * CPX
    return x0 < cam_x + W + 24 and x0 + CPX > cam_x - 24 and y0 < cam_y + H + 24 and y0 + CPX > cam_y - 24
  end
  function FOE.spawn_around()
    if FOE.quiet then return end                  -- (the tests on the PC)
    for cy = fdiv(cam_y - MARGIN, CPX), fdiv(cam_y + H + MARGIN, CPX) do
      for cx = fdiv(cam_x - MARGIN, CPX), fdiv(cam_x + W + MARGIN, CPX) do
        local ch = chunk(cx, cy)
        if ch and ch.ready and not ch.spawned and not on_screen_chunk(ch) then populate(ch) end
      end
    end
  end

  ----------------------------------------------------------- sounds
  local function sfx_thud() note(1, 90, 120, NOISE, 110); note(2, 160, 80, SQUARE, 50) end
  local function sfx_cry(o)
    local k = o.def.kind
    if k == "beast" then note(3, 180, 220, SAW, 70); note(2, 120, 260, NOISE, 50)
    elseif k == "horror" then note(3, 900, 300, TRIANGLE, 50); note(2, 1340, 300, TRIANGLE, 30)
    else note(3, 220, 200, SAW, 50) end
  end
  local function sfx_roar() note(0, 60, 700, SAW, 120); note(1, 45, 800, NOISE, 110); note(2, 90, 600, SQUARE, 60) end
  local function sfx_boom() note(0, 40, 500, NOISE, 200); note(1, 55, 400, SQUARE, 120) end

  ----------------------------------------------------------- the hunter hits them
  local function bleed(o, n)
    for _ = 1, n do
      spawn(o.x + (math.random() - 0.5) * 6, o.y - 10 - math.random(8), (math.random() - 0.5) * 2.2,
            -math.random() * 1.6, 18 + math.random(16), 5)
    end
  end
  -- staggered: reeling, open to a visceral attack for a while
  local function stagger(o, ticks)
    o.act, o.beam, o.stag = "stagger", nil, ticks or 110
    play(o, "hurt")
    note(1, 2400, 140, METAL, 70); note(2, 1200, 220, TRIANGLE, 60)
  end
  FOE.stagger = stagger

  -- damage to a creature; flinch: the blow (or the shot) stops what it does.
  -- A boss flinches only when the blows add up (its poise breaks)
  local function harm(o, dmg, flinch)
    if o.act == "dead" then return end
    o.hp = o.hp - dmg
    o.alert = true
    bleed(o, 6 + dmg * 3)
    sfx_thud()
    if o.boss and not o.awake then o.awake = true; FOE.boss = o end
    local reeling = o.act == "stagger" or o.act == "held"
    if o.boss and o.hp > 0 and not reeling then
      o.poise = (o.poise or 0) + dmg
      if o.poise >= 16 then
        o.poise = 0
        stagger(o, 80)
        return
      end
    end
    if o.hp <= 0 then
      o.act, o.corpse, o.ended = "dead", 0, false
      play(o, "death")
      sfx_cry(o)
      FOE.killed = FOE.killed + 1
      if o.boss then
        FOE.slain[o.home] = true
        FOE.won, FOE.won_t = o.def.title, 0
        if FOE.boss == o then FOE.boss = nil end
        sfx_roar()
      end
    elseif flinch and not reeling then
      o.act, o.beam = "hurt", nil
      play(o, "hurt")
    end
  end
  FOE.harm = harm

  -- the nearest living creature within range of the hunter
  function FOE.nearest(range)
    local best, bd = nil, range * range
    for _, o in ipairs(list) do
      if o.act ~= "dead" then
        local dx, dy = o.x - P.x, o.y - P.y
        local d2 = dx * dx + dy * dy
        if d2 < bd then best, bd = o, d2 end
      end
    end
    return best
  end

  -- a blow of the saw cleaver: every creature in reach, ahead of the hunter.
  -- A charged blow in the back staggers (then comes the visceral attack)
  function FOE.strike(dmg, reach, cone, charged)
    local v = DIRV[P.dir + 1]
    local n = 0
    for _, o in ipairs(list) do
      if o.act ~= "dead" and o.act ~= "held" then
        local dx, dy = o.x - P.x, o.y - P.y
        local dd = sqrt(dx * dx + dy * dy)
        if dd < reach + o.st.r and (dd < 6 or (dx * v[1] + dy * v[2]) / dd > cone) then
          local f = DIRV[o.dir + 1]
          local behind = dd > 1 and (f[1] * dx + f[2] * dy) / dd > 0.35   -- it faces away from the hunter
          harm(o, dmg, not o.boss)
          if charged and behind and o.act ~= "dead" then stagger(o, 110) end
          n = n + 1
        end
      end
    end
    return n
  end

  -- a staggered creature right ahead of the hunter: the visceral attack
  function FOE.visceral_target()
    local v = DIRV[P.dir + 1]
    for _, o in ipairs(list) do
      if o.act == "stagger" then
        local dx, dy = o.x - P.x, o.y - P.y
        local dd = sqrt(dx * dx + dy * dy)
        if dd < 24 + o.st.r * 0.6 and (dd < 10 or (dx * v[1] + dy * v[2]) / dd > 0.2) then return o end
      end
    end
  end
  -- the hand torn out: a great wound, a fountain of blood
  function FOE.visceral(o, dmg)
    o.act, o.stag = nil, 0
    bleed(o, 40)
    note(0, 70, 400, SAW, 150); note(1, 300, 260, NOISE, 140)
    FOE.shake = 8
    harm(o, dmg, true)
  end
  -- the shot: the first creature on its way. A boss caught winding up a
  -- blow is staggered (as the hunters parry with their guns)
  function FOE.shot(x0, y0, x1, y1)
    local best, bt
    local lx, ly = x1 - x0, y1 - y0
    local ll = lx * lx + ly * ly
    if ll < 1 then return nil end
    for _, o in ipairs(list) do
      if o.act ~= "dead" then
        local ox, oy = o.x, o.y - 12
        local tt = ((ox - x0) * lx + (oy - y0) * ly) / ll
        if tt > 0 and tt <= 1 then
          local px, py = x0 + lx * tt, y0 + ly * tt
          local ex, ey = ox - px, oy - py
          if ex * ex + ey * ey < (o.st.r + 6) ^ 2 and (not bt or tt < bt) then best, bt = o, tt end
        end
      end
    end
    if best then
      local o = best
      local a = o.act and o.def.a[o.anim]
      local hits = a and (a.hit or a.fire or a.slam or a.beam)
      local winding = o.act and o.act ~= "hurt" and o.act ~= "stagger" and o.act ~= "held" and hits and
                      o.f < hits[1]
      harm(o, 1, not o.boss)
      if winding and o.act ~= "dead" then stagger(o, 110) end      -- the parry
      return x0 + lx * bt, y0 + ly * bt
    end
  end

  ----------------------------------------------------------- they hit the hunter
  local function reach_player(o, reach, cone)
    local dx, dy = P.x - o.x, P.y - o.y
    local dd = sqrt(dx * dx + dy * dy)
    if dd > reach + 6 then return false end
    if dd < 8 then return true end
    local v = DIRV[o.dir + 1]
    return (dx * v[1] + dy * v[2]) / dd > (cone or 0.3)
  end
  local function ring(x, y, rmax, dmg, heavy, c)
    rings[#rings + 1] = { x = x, y = y, r = 2, rmax = rmax, dmg = dmg, heavy = heavy, c = c or 0xC8B898, hit = false }
  end

  -- what happens on the frames that matter: blows, shots, bombs, slams
  local function event(o)
    local a = o.def.a[o.anim]
    local f = o.f
    local st = o.st
    if has(a.hit, f) then
      local reach, cone = st.reach, 0.3
      if o.anim == "whirl" then reach, cone = 40, -1 end
      if o.anim == "combo1" and o.name == "watcher" then cone = -0.2 end
      if reach_player(o, reach, cone) then hurt(o.boss and 3 or st.dmg, st.heavy or (o.boss and f == a.hit[#a.hit] and
                                                                                    math.random() < 0.4)) end
      note(1, o.boss and 600 or 1100, 110, NOISE, o.boss and 80 or 50)
    end
    if has(a.fire, f) then
      local mx, my = point(o, 2)
      FOE.flash = { mx, my, 6 }
      note(0, 600, 220, NOISE, 180); note(1, 70, 200, SQUARE, 110)
      if o.name == "father" then
        -- the blunderbuss: a spray of shot, close and wide
        local dx, dy = P.x - o.x, P.y - o.y
        local dd = sqrt(dx * dx + dy * dy)
        local v = DIRV[o.dir + 1]
        if dd < 80 and (dd < 8 or (dx * v[1] + dy * v[2]) / dd > 0.72) then hurt(3, dd < 40) end
        for _ = 1, 14 do
          local sp = 2 + math.random() * 2
          local an = math.atan(v[2], v[1]) + (math.random() - 0.5) * 0.9
          spawn(mx, my, cos(an) * sp, sin(an) * sp, 12 + math.random(10), 4)
        end
      else
        -- the rifle: a ball that flies until it hits
        local dx, dy = P.x - o.x, P.y - o.y
        local dd = max(1, sqrt(dx * dx + dy * dy))
        shots[#shots + 1] = { x = o.x, y = o.y, h = o.y - my, vx = dx / dd * 3.4, vy = dy / dd * 3.4, t = 70,
                              kind = "ball", dmg = st.dmg }
      end
    end
    if has(a.throw, f) then
      local hx, hy = point(o, 2)
      local tx, ty = P.x + (math.random() - 0.5) * 16, P.y + (math.random() - 0.5) * 10
      shots[#shots + 1] = { x = o.x, y = o.y, h = o.y - hy, x0 = o.x, y0 = o.y, h0 = o.y - hy, tx = tx, ty = ty,
                            t = 0, T = 42, kind = "bomb" }
      note(2, 300, 200, NOISE, 60)
    end
    if has(a.slam, f) then
      local sx, sy = o.x, o.y
      if o.name == "butcher" then sx, sy = point(o, 1); sy = sy + 24 end
      if o.name == "hound" then
        local v = DIRV[o.dir + 1]
        sx, sy = o.x + v[1] * 32, o.y + v[2] * 32
      end
      ring(sx, sy, o.name == "watcher" and 74 or 62, 3, true)
      FOE.shake = 14
      sfx_boom()
      for _ = 1, 16 do
        local an = math.random() * 2 * PI
        spawn(sx + cos(an) * 6, sy + sin(an) * 4, cos(an) * 1.2, sin(an) * 0.7 - 0.4, 20 + math.random(14), 3)
      end
    end
    if has(a.howl, f) then
      ring(o.x, o.y, 110, 0, false, 0xA0A8B8)
      FOE.shake = 24
      o.fury = 420
      sfx_roar()
    end
    if has(a.beam, f) then
      local ex, ey = point(o, 2)
      o.beam = { ex = ex, ey = ey, tx = P.x, ty = P.y - 10, t = 70 }
      note(0, 1400, 900, TRIANGLE, 60); note(1, 1880, 900, TRIANGLE, 40)
    end
  end

  -- what a boss does next, from how far the hunter is
  local function boss_choice(o, dd)
    local n = o.name
    local r = math.random()
    if n == "butcher" then
      if dd < 46 then return r < 0.4 and "attack" or r < 0.7 and "combo1" or r < 0.9 and "combo2" or "slam" end
      if dd < 80 then return r < 0.6 and "slam" or "throw" end
      if dd < 150 then return r < 0.5 and "throw" or nil end
    elseif n == "hound" then
      if dd < 48 then return r < 0.35 and "attack" or r < 0.65 and "combo1" or r < 0.9 and "combo2" or "howl" end
      if dd < 130 then return r < 0.5 and "pounce" or (not o.fury and r < 0.65) and "howl" or nil end
    elseif n == "father" then
      if dd < 40 then return r < 0.3 and "attack" or r < 0.55 and "combo1" or r < 0.75 and "combo2" or "whirl" end
      if dd < 76 then return r < 0.55 and "blast" or nil end
    elseif n == "watcher" then
      if dd < 50 then return r < 0.3 and "attack" or r < 0.55 and "combo1" or r < 0.8 and "combo2" or "grasp" end
      if dd < 76 then return r < 0.5 and "grasp" or "beam" end
      if dd < 170 then return r < 0.4 and "beam" or nil end
    end
  end

  ----------------------------------------------------------- every tick
  local function think(o, alive)
    local st = o.st
    local dx, dy = P.x - o.x, P.y - o.y
    local dd = sqrt(dx * dx + dy * dy)
    if o.act == "dead" then
      if not o.ended then
        o.ended = step(o)
        if o.newf and o.f == 4 then note(0, 50, 200, NOISE, 90) end
      end
      o.corpse = o.corpse + 1
      return
    end
    if o.act == "stagger" then
      if o.f < 2 then step(o) end                 -- reeling: held on the second frame of its hurt
      o.stag = o.stag - 1
      if o.stag <= 0 then
        o.act, o.cd = nil, 30
        play(o, "idle")
      end
      return
    end
    if o.act == "held" then                       -- in the hunter's grip
      if P.vic ~= o then o.act, o.stag = "stagger", 20 end
      return
    end
    if o.act then
      local done = step(o, o.fury and 1.25 or 1)
      if o.newf then event(o) end
      -- a few creatures lunge in their blow (the pounce flies in its frames)
      if (o.anim == "attack" or o.anim:sub(1, 5) == "combo") and o.def.a[o.anim].hit and
             o.f <= o.def.a[o.anim].hit[1] and dd > st.r + 8 then
        local v = DIRV[o.dir + 1]
        local k = o.name == "dog" and 1.4 or 0.3
        move(o, v[1] * k, v[2] * k)
      end
      if done then
        -- the body ends ahead of where it stood (a pounce): it is there now
        local sh = o.def.a[o.anim].shift
        if sh then
          local v = DIRV[o.dir + 1]
          move(o, v[1] * sh, v[2] * sh)
        end
        o.act = nil
        o.cd = (o.boss and 30 or 50) + math.random(o.boss and 50 or 70)
        play(o, "idle")
      end
      return
    end
    if o.fury then o.fury = o.fury - 1; if o.fury <= 0 then o.fury = nil end end
    if o.cd > 0 then o.cd = o.cd - 1 end
    if o.boss and not o.awake then
      if alive and dd < 112 then
        o.awake = true
        FOE.boss = o
        sfx_roar()
      end
      step(o)
      return
    end
    -- a boss keeps to its ground
    local hx, hy = o.hx - o.x, o.hy - o.y
    if o.boss and hx * hx + hy * hy > 200 * 200 then
      o.dir = dir_to(hx, hy)
      local v = DIRV[o.dir + 1]
      move(o, v[1] * st.sp, v[2] * st.sp)
      if o.anim ~= "walk" then play(o, "walk") end
      step(o)
      return
    end
    if alive and not o.alert and dd < st.sight then
      o.alert = true
      if math.random() < 0.5 then sfx_cry(o) end
    end
    if o.alert and alive and dd > st.sight * 1.8 and not o.boss then o.alert = false end
    if o.alert and alive then
      o.dir = dir_to(dx, dy)
      local want
      if o.boss then
        if o.cd <= 0 then want = boss_choice(o, dd) end
      elseif o.cd <= 0 and dd < st.reach + (st.ranged and 0 or 4) then
        want = "attack"
      end
      if want then
        o.act = want
        play(o, want)
        return
      end
      local close = st.ranged and 90 or (st.reach * 0.7 + st.r * 0.3)
      if dd > close then
        local sp = st.sp * (o.fury and 1.5 or 1)
        move(o, dx / dd * sp, dy / dd * sp)
        if o.anim ~= "walk" then play(o, "walk") end
        step(o, (o.fury and 1.5 or 1) * (o.name == "dog" and 1.2 or 1))
        return
      end
    end
    if o.anim ~= "idle" then play(o, "idle") end
    step(o)
  end

  -- passive (the title): nobody hunts, the ones on screen breathe
  function FOE.update(passive)
    local alive = P.act ~= "dead" and not passive
    if FOE.shake > 0 then FOE.shake = FOE.shake - 1 end
    if FOE.won then FOE.won_t = FOE.won_t + 1; if FOE.won_t > 300 then FOE.won = nil end end
    if FOE.flash then FOE.flash[3] = FOE.flash[3] - 1; if FOE.flash[3] <= 0 then FOE.flash = nil end end
    local i = 1
    while i <= #list do
      local o = list[i]
      local dx, dy = o.x - P.x, o.y - P.y
      local far = dx * dx + dy * dy > 300 * 300
      -- gone with their streets, or long dead
      local cx, cy = fdiv(o.x, CPX), fdiv(o.y, CPX)
      if (far and not chunk(cx, cy)) or (o.act == "dead" and o.corpse > 1200 and far) then
        if FOE.boss == o then FOE.boss = nil end
        table.remove(list, i)
      else
        if o.act or o.alert or o.boss then
          think(o, alive)
        elseif not far then
          -- out of sight it only stands and breathes (half as often)
          local s = o.st.sight
          if dx * dx + dy * dy < s * s then think(o, alive)
          elseif (t + i) % 2 == 0 then step(o, 2) end
        elseif (t + i) % 2 == 0 and o.x > cam_x - 40 and o.x < cam_x + W + 40 and o.y > cam_y - 20 and
               o.y < cam_y + H + 80 then
          step(o, 2)
        end
        o.z = o.act == "dead" and o.y - 6 or o.y
        i = i + 1
      end
    end
    -- creatures on the move do not walk through one another (every other tick)
    if t % 2 == 0 then
      for a = 1, #list do
        local p = list[a]
        if p.alert and p.act ~= "dead" then
          for b = 1, #list do
            local q = list[b]
            if q ~= p and q.act ~= "dead" then
              local dx, dy = q.x - p.x, q.y - p.y
              local rr = (p.st.r + q.st.r) * 0.7
              local d2 = dx * dx + dy * dy
              if d2 < rr * rr and d2 > 0.01 then
                local d = sqrt(d2)
                local push = (rr - d) * 0.5 / d
                move(p, -dx * push, -dy * push)
              end
            end
          end
        end
      end
    end
    -- balls and bombs
    for k = #shots, 1, -1 do
      local s = shots[k]
      if s.kind == "ball" then
        s.x, s.y, s.t = s.x + s.vx, s.y + s.vy, s.t - 1
        local dx, dy = P.x - s.x, P.y - s.y
        if alive and dx * dx + dy * dy < 64 then
          hurt(s.dmg, false)
          s.t = 0
        elseif solid_at(s.x, s.y) then
          for _ = 1, 4 do spawn(s.x, s.y - s.h, (math.random() - 0.5) * 2, -math.random(), 10, 4) end
          s.t = 0
        end
        if s.t <= 0 then table.remove(shots, k) end
      else
        s.t = s.t + 1
        local u = s.t / s.T
        s.x, s.y = s.x0 + (s.tx - s.x0) * u, s.y0 + (s.ty - s.y0) * u
        s.h = s.h0 * (1 - u) + sin(u * PI) * 46
        if math.random() < 0.6 then spawn(s.x, s.y - s.h, 0, -0.3, 12, 1) end
        if s.t >= s.T then
          burns[#burns + 1] = { x = s.x, y = s.y, t = 260, acc = 0 }
          sfx_boom()
          for _ = 1, 20 do
            local an = math.random() * 2 * PI
            spawn(s.x, s.y - 2, cos(an) * 1.4, sin(an) * 0.8 - 0.8, 16 + math.random(16), 1)
          end
          table.remove(shots, k)
        end
      end
    end
    -- fire on the stones: it burns a while
    for k = #burns, 1, -1 do
      local b = burns[k]
      b.t = b.t - 1
      b.acc = b.acc + (b.t > 60 and 1.2 or 0.4)
      while b.acc >= 1 do
        b.acc = b.acc - 1
        spawn(b.x + (math.random() - 0.5) * 26, b.y + (math.random() - 0.5) * 12, (math.random() - 0.5) * 0.3,
              -0.5 - math.random() * 0.8, 14 + math.random(20), 1)
      end
      local ex, ey = (P.x - b.x) / 16, (P.y - b.y) / 9
      if alive and ex * ex + ey * ey < 1 then hurt(1, false) end
      if b.t <= 0 then table.remove(burns, k) end
    end
    -- shock waves along the ground
    for k = #rings, 1, -1 do
      local g = rings[k]
      g.r = g.r + 2.4
      if g.dmg > 0 and not g.hit and alive then
        local dx, dy = P.x - g.x, (P.y - g.y) * 1.6
        local dd = sqrt(dx * dx + dy * dy)
        if abs(dd - g.r) < 7 then g.hit = true; hurt(g.dmg, g.heavy) end
      end
      if g.r >= g.rmax then table.remove(rings, k) end
    end
    -- the Watcher's gaze
    for _, o in ipairs(list) do
      local b = o.beam
      if b then
        b.t = b.t - 1
        if b.t <= 0 or o.act == "dead" then
          o.beam = nil
        elseif alive then
          local lx, ly = b.tx - b.ex, b.ty - b.ey
          local ll = lx * lx + ly * ly
          local px, py = P.x, P.y - 10
          local tt = max(0, ((px - b.ex) * lx + (py - b.ey) * ly) / ll)
          local qx, qy = b.ex + lx * tt - px, b.ey + ly * tt - py
          if qx * qx + qy * qy < 64 then hurt(2, false) end
        end
      end
    end
    if FOE.boss and (FOE.boss.act == "dead" or not alive) then
      if not alive then FOE.boss.awake = false end
      FOE.boss = nil
    end
  end

  -- after the hunter dies: the town fills again, the bosses wait whole
  function FOE.reset()
    FOE.respawns = FOE.respawns + 1
    for k = #list, 1, -1 do
      local o = list[k]
      if o.boss and o.act ~= "dead" then
        o.x, o.y, o.hp, o.awake, o.act, o.alert, o.beam, o.fury = o.hx, o.hy, o.st.hp, false, nil, false, nil, nil
        play(o, "idle")
      else
        table.remove(list, k)
      end
    end
    for _, ch in pairs(chunks) do
      ch.spawned = false
    end
    for k = #shots, 1, -1 do shots[k] = nil end
    for k = #rings, 1, -1 do rings[k] = nil end
    for k = #burns, 1, -1 do burns[k] = nil end
    FOE.boss = nil
  end

  ----------------------------------------------------------- drawing
  function FOE.draw(o)
    local fr, flip = frame(o)
    if flip then
      sspr(fr[1], fr[2], fr[3], fr[4], floor(o.x) - (fr[3] - fr[5]), floor(o.y) - fr[6], true)
    else
      sspr(fr[1], fr[2], fr[3], fr[4], floor(o.x) - fr[5], floor(o.y) - fr[6])
    end
  end
  -- the lights they carry: torches, the lantern's head, the gaze, flashes
  function FOE.lights()
    for _, o in ipairs(list) do
      if o.act ~= "dead" and abs(o.x - P.x) < 200 and abs(o.y - P.y) < 200 then
        if o.st.torch then
          local x, y = point(o, 2)
          glow(x, y, 44 + sin(t * 0.4 + o.x) * 2, 6, 0.5)
        elseif o.st.lantern then
          local x, y = point(o, 2)
          glow(x, y, 26, 3, 0.6)
        end
      end
      if o.beam then glow(o.beam.ex, o.beam.ey, 40, 6, 0.4) end
    end
    for _, b in ipairs(burns) do glow(b.x, b.y - 4, b.t > 60 and 46 or 30, 6, 0.5) end
    for _, s in ipairs(shots) do if s.kind == "bomb" then glow(s.x, s.y - s.h, 22, 5, 0.5) end end
    if FOE.flash then glow(FOE.flash[1], FOE.flash[2], 30 + FOE.flash[3] * 8, 7, 0.4) end
  end
  -- drawn after the light: what shines
  function FOE.fx()
    for _, s in ipairs(shots) do
      if s.kind == "ball" then
        line(s.x, s.y - s.h, s.x - s.vx * 2, s.y - s.h - s.vy * 2, 0xF8E8A0)
      else
        circfill(s.x, s.y - s.h, 2, 0xA06030)
        pset(s.x, s.y - s.h - 2, (t // 2) % 2 == 0 and 0xF8F8D8 or 0xF8C050)
      end
    end
    for _, b in ipairs(burns) do
      local k = b.t > 60 and 1 or b.t / 60
      local fl = sin(t * 0.5 + b.x)
      circfill(b.x, b.y, (8 + fl) * k, 0xA83818)
      circfill(b.x - 3, b.y - 1, (5 + fl * 0.5) * k, 0xE06020)
      circfill(b.x + 2, b.y - 2, 3 * k, 0xF8C050)
    end
    for _, g in ipairs(rings) do
      circ(g.x, g.y, g.r, g.c)
      if g.r > 4 then circ(g.x, g.y, g.r - 3, 0x605850) end
    end
    for _, o in ipairs(list) do
      local b = o.beam
      if b then
        local w = b.t > 60 and 1 or 2
        local lx, ly = b.tx - b.ex, b.ty - b.ey
        local ll = max(1, sqrt(lx * lx + ly * ly))
        local ex, ey = b.ex + lx / ll * 170, b.ey + ly / ll * 170
        line(b.ex, b.ey, ex, ey, 0xB0F0F8)
        if w > 1 then
          line(b.ex + 1, b.ey, ex + 1, ey, 0x58C8D8)
          line(b.ex - 1, b.ey, ex - 1, ey, 0x58C8D8)
        end
        circfill(b.ex, b.ey, 2 + (t // 3) % 2, 0xF8F0C0)
      end
    end
    if FOE.flash then
      local f = FOE.flash
      circfill(f[1], f[2], f[3] > 3 and 4 or 2, 0xF8C050)
      circfill(f[1], f[2], 1, 0xF8F8D8)
    end
    for _, o in ipairs(list) do
      if o.act == "stagger" and (t // 4) % 2 == 0 then FOE.mark(o, 0xF8F8E8) end
    end
  end
  -- a small diamond over a creature's head
  function FOE.mark(o, c)
    local fr = frame(o)
    local x, y = floor(o.x), floor(o.y) - fr[6] - 6
    pset(x, y - 2, c); pset(x - 2, y, c); pset(x + 2, y, c); pset(x, y + 2, c)
    pset(x - 1, y - 1, c); pset(x + 1, y - 1, c); pset(x - 1, y + 1, c); pset(x + 1, y + 1, c)
  end

  -- the boss's name and health, at the foot of the screen
  function FOE.hud()
    local o = FOE.boss
    if o and o.awake and o.act ~= "dead" then
      rectfill(0, 224, W, 32, 0x000000)
      local name = o.def.title
      print(name, (W - #name * 8) // 2 // 8 * 8, 224, 0xD8C8A0)
      rectfill(23, 243, 210, 6, 0x180808)
      rectfill(24, 244, floor(208 * max(0, o.hp) / o.st.hp), 4, 0xA01818)
    end
    if FOE.won then
      local k = FOE.won_t
      rectfill(0, 104, W, 48, 0x080604)
      print("PREY SLAUGHTERED", 0, 112, k > 20 and 0xE8C878 or 0x786040, 2)
    end
  end
end

local function respawn()
  FOE.reset()
  P.x, P.y = P.spawn and P.spawn[1] or P.home[1], P.spawn and P.spawn[2] or P.home[2]
  P.hp, P.act, P.inv, P.dir, P.rally, P.st, P.lock, P.vic = HP_MAX, nil, 90, 0, 0, ST_MAX, nil, nil
  play(xname("idle"))
  cam_x, cam_y = P.x - W / 2, P.y - H * 0.62
end

local function update_play()
  local dx, dy = 0, 0
  if btn(0) then dx = dx - 1 end
  if btn(1) then dx = dx + 1 end
  if btn(2) then dy = dy - 1 end
  if btn(3) then dy = dy + 1 end
  if P.inv > 0 then P.inv = P.inv - 1 end
  if P.rally_t > 0 then P.rally_t = P.rally_t - 1; if P.rally_t == 0 then P.rally = 0 end end
  -- the shoulder buttons (L1 locks on, R1 the heavy blow), B tapped or held
  local pd = pad()
  local l1, r1 = pd & 1024 ~= 0, pd & 2048 ~= 0
  local l1p, r1p = l1 and not P.l1, r1 and not P.r1
  P.l1, P.r1 = l1, r1
  if btn(5) then P.bt, P.brel = P.bt + 1, 0 else P.brel, P.bt = P.bt, 0 end
  if P.st_wait > 0 then P.st_wait = P.st_wait - 1
  elseif P.st < ST_MAX then P.st = min(ST_MAX, P.st + 1.4) end
  if l1p then
    P.lock = not P.lock and FOE.nearest(150) or nil
    note(2, P.lock and 1600 or 800, 60, TRIANGLE, 40)
  end
  local L = P.lock
  if L and (L.act == "dead" or abs(L.x - P.x) + abs(L.y - P.y) > 260) then P.lock = nil end
  if flash > 0 then flash = flash - 1 end
  if tracer then tracer[5] = tracer[5] - 1; if tracer[5] <= 0 then tracer = nil end end
  local pcx, pcy = fdiv(P.x, CPX), fdiv(P.y, CPX)
  -- lamps in reach
  near_lamp = nil
  if not P.act then
    for cy = pcy - 1, pcy + 1 do
      for cx = pcx - 1, pcx + 1 do
        local ch = chunk(cx, cy)
        if ch and ch.ready then
          for _, l in ipairs(ch.lamps) do
            if abs(l.x - P.x) < 22 and abs(l.y - P.y) < 18 then
              if not lamp_state[l.key] then near_lamp = l
              elseif t % 40 == 0 and P.hp < HP_MAX then P.hp = P.hp + 1 end     -- a lit lamp heals
            end
          end
        end
      end
    end
  end

  local act = P.act
  if not act then
    P.moving = dx ~= 0 or dy ~= 0
    if btnp(4) and near_lamp then
      lamp_state[near_lamp.key] = true
      lamps_lit = lamps_lit + 1
      P.hp, P.rally = HP_MAX, 0
      P.spawn = { near_lamp.x, near_lamp.y + 14 }
      sfx_light()
      for k = 1, 24 do
        local a = math.random() * 2 * PI
        spawn(near_lamp.x, near_lamp.y - 66, cos(a) * 0.8, sin(a) * 0.8 - 0.6, 30 + math.random(20), 4)
      end
    elseif btnp(4) and FOE.visceral_target() then
      visceral(FOE.visceral_target())
    elseif btnp(4) and P.st > 0 then
      attack(1, dx, dy)
    elseif r1p and P.st > 0 then
      heavy(dx, dy)
    elseif btnp(6) then
      if P.moving then P.dir = DIRS[dy][dx] end
      if P.moving then P.act = "shoot"; play(xname("shoot")) else shoot() end
    elseif btnp(7) then
      P.act = P.ext and "close" or "open"
      play("open", P.ext)
    elseif P.brel > 0 and P.brel < 10 and P.st > 0 then
      dodge(dx, dy)
    elseif P.moving then
      local run = P.bt >= 10 and P.st > 0 and not P.lock
      if run then P.st, P.st_wait = P.st - 0.45, 30 end
      P.dir = P.lock and FOE.dir_to(P.lock.x - P.x, P.lock.y - P.y) or DIRS[dy][dx]
      local sp = run and 1.55 or (P.lock and 0.8 or 0.92)
      if dx ~= 0 and dy ~= 0 then sp = sp * 0.7071 end
      walk_by(dx * sp, dy * sp)
      if P.anim ~= xname("walk") then play(xname("walk")) end
      step_anim(run and 1.5 or 1)
      if P.newf and (P.f == 3 or P.f == 7) then sfx_step() end
    else
      if P.lock then P.dir = FOE.dir_to(P.lock.x - P.x, P.lock.y - P.y) end
      if P.anim ~= xname("idle") then play(xname("idle")) end
      step_anim()
    end
  elseif act == "attack" then
    local a = HUNT[P.anim]
    local done = step_anim()
    if P.f <= a.hit then forward(P.ext and 0.45 or 0.35) end
    if P.newf and P.f == a.hit then
      sfx_swing(P.ext)
      local dmg = (P.ext and 2 or 1) + (P.combo == 3 and 1 or 0)
      rally(FOE.strike(dmg, P.ext and 34 or 26, P.combo == 3 and 0.5 or 0.1))
    end
    -- the tip of the blade leaves a trail through the blow
    if P.f >= a.hit - 2 and P.f <= a.hit + 1 then
      local fr = a.d[P.dir + 1][P.f]
      P.trail[#P.trail + 1] = { P.x + fr[7], P.y + fr[8], 10 }
    end
    -- after the blow: A goes on, Y transforms the blade in a blow, R1 strikes heavy
    if btnp(4) and P.f >= a.hit - 1 and P.combo < 3 then P.queued = "a" end
    if btnp(7) and P.f >= a.hit - 1 then P.queued = "y" end
    if r1p and P.f >= a.hit - 1 then P.queued = "r" end
    if P.queued and P.f > a.hit + 1 and P.st > 0 then
      local q = P.queued
      if q == "y" then trick() elseif q == "r" then heavy(dx, dy) else attack(P.combo + 1, dx, dy) end
    elseif done then
      P.act, P.combo = nil, 0
    end
  elseif act == "heavy" then
    local a = HUNT[P.anim]
    if P.f == a.charge and r1 and P.charge < 45 then
      -- R1 held at the top of the wind-up: charging
      P.charge = P.charge + 1
      P.st_wait = 30
      if P.charge == 20 then P.charged = true; note(1, 220, 300, SAW, 60); note(2, 880, 300, TRIANGLE, 40) end
    else
      local done = step_anim()
      if P.f <= a.hit then forward(P.ext and 0.4 or 0.3) end
      if P.newf and P.f == a.hit then
        sfx_swing(true)
        local dmg = (P.ext and 4 or 3) + (P.charged and 3 or 0)
        rally(FOE.strike(dmg, P.ext and 36 or 30, 0.2, P.charged))
        if P.charged then FOE.shake = 6 end
      end
      if P.f >= a.hit - 2 and P.f <= a.hit + 1 then
        local fr = a.d[P.dir + 1][P.f]
        P.trail[#P.trail + 1] = { P.x + fr[7], P.y + fr[8], 12 }
      end
      if done then P.act, P.combo, P.charged = nil, 0, false end
    end
  elseif act == "trick" then
    local a = HUNT[P.anim]
    local done = step_anim()
    if P.f <= a.hit then forward(0.35) end
    if P.newf and P.f == a.hit then
      sfx_swing(true)
      rally(FOE.strike(P.ext and 3 or 2, 32, 0.0))
    end
    if P.newf and P.f == a.lock then P.ext = not P.ext; sfx_clank() end
    if P.f >= a.hit - 2 and P.f <= a.hit + 1 then
      local fr = a.d[P.dir + 1][P.f]
      P.trail[#P.trail + 1] = { P.x + fr[7], P.y + fr[8], 10 }
    end
    if btnp(4) and P.f >= a.hit - 1 then P.queued = "a" end
    if P.queued and P.f > a.lock and P.st > 0 then
      attack(min(P.combo + 1, 3), dx, dy)               -- the combo goes on, in the other form
    elseif done then
      P.act, P.combo = nil, 0
    end
  elseif act == "qstep" or act == "roll" then
    local done = step_anim()
    local f = P.f
    local sp
    if act == "roll" then sp = (f >= 2 and f <= 6) and 2.2 or 0
    else sp = (f >= 2 and f <= 4) and 3.0 or f == 5 and 1.0 or 0 end
    if sp > 0 then walk_by(P.dv[1] * sp, P.dv[2] * sp) end
    if done then P.act = nil end
  elseif act == "visceral" then
    local a = HUNT[P.anim]
    local done = step_anim()
    if P.newf and P.f == a.hit and P.vic then
      FOE.visceral(P.vic, P.ext and 14 or 12)
      rally(P.rally)
    end
    if done then P.act, P.vic, P.inv = nil, nil, 0 end
  elseif act == "shoot" then
    local done = step_anim()
    if P.newf and P.f == HUNT[P.anim].fire then fire() end
    if done then P.act = nil end
  elseif act == "open" or act == "close" then
    local done = step_anim()
    if P.newf and P.f == HUNT.open.lock then sfx_clank() end
    if done then P.act, P.ext = nil, act == "open" end
  elseif act == "backstep" then
    local done = step_anim()
    if P.f >= 2 and P.f <= 5 then forward(P.f >= 3 and P.f <= 4 and -2.4 or -1.2) end
    if done then P.act = nil end
  elseif act == "hurt" then
    local done = step_anim()
    if P.f <= 2 then forward(-0.6) end
    if done then P.act = nil end
  elseif act == "down" then
    local done = step_anim()
    if P.f <= 5 then forward(-1.4) end
    if P.newf and P.f == 5 then sfx_fall() end
    if done then P.act, P.lie = "lying", 50 end
  elseif act == "lying" then
    P.lie = P.lie - 1
    if P.lie <= 0 or (P.lie < 30 and (btnp(4) or btnp(5))) then
      P.act = "getup"
      play(xname("getup"))
    end
  elseif act == "getup" then
    if step_anim() then P.act, P.inv = nil, 40 end
  elseif act == "dead" then
    if not step_anim() then
      if P.newf and P.f == 8 then sfx_fall() end
    else
      died_t = died_t + 1
      if died_t > 150 then respawn() end
    end
  end
  for i = #P.trail, 1, -1 do
    local tr = P.trail[i]
    tr[3] = tr[3] - 1
    if tr[3] <= 0 then table.remove(P.trail, i) end
  end

  -- fire burns: braziers and pyres
  if P.act ~= "dead" then
    for cy = pcy - 1, pcy + 1 do
      for cx = pcx - 1, pcx + 1 do
        local ch = chunk(cx, cy)
        if ch and ch.ready then
          for _, f in ipairs(ch.fires) do
            local bx, by = f.x, f.y + (f.big and 10 or 25)
            local r = f.big and 26 or 16
            local ex, ey = (P.x - bx) / r, (P.y - by) / (r * 0.6)
            if ex * ex + ey * ey < 1 then hurt(f.big and 3 or 1, f.big and math.random() < 0.5) end
          end
        end
      end
    end
  end

  -- the camera follows, a little ahead of the hunter
  local tx, ty = P.x - W / 2, P.y - H * 0.62
  cam_x = cam_x + (tx - cam_x) * 0.12
  cam_y = cam_y + (ty - cam_y) * 0.12
  -- a new district: its name
  local d = district(pcx, pcy)
  if d ~= here then
    here = d
    banner, banner_t = d.name, 200
  end
  if banner_t > 0 then banner_t = banner_t - 1 end
  FOE.update()
end

-- for the tests on the PC (tests/yharnam/sim.lua)
YHARNAM = { road_at = road_at, district = district, chunk = chunk, ensure = ensure, player = P,
            blocked = blocked, lamps = lamp_state, kinds = { road = K_ROAD, walk = K_WALK, house = K_HOUSE },
            camera = function() return cam_x, cam_y end, CS = CS, TS = TS, SPR = SPR, FACADE = FACADE,
            HUNT = HUNT, FOES = FOES, FOE = FOE, hurt = hurt, flash = function() return flash end, dirs = DIRS,
            teleport = function(x, y)
              P.x, P.y = x, y
              cam_x, cam_y = x - W / 2, y - H * 0.62
              state = "play"
            end }

-- the animation viewer of the title screen: every animation of the hunter
-- and of every creature, every direction
local GALLERY = {}
for _, n in ipairs({ "idle", "walk", "shoot", "slash1", "slash2", "slash3", "backstep", "hurt1", "hurt2", "hurt3",
                     "down", "getup", "death", "open", "idle_x", "walk_x", "shoot_x", "xslash1", "xslash2",
                     "xslash3", "backstep_x", "hurt1_x", "hurt2_x", "hurt3_x", "down_x", "getup_x",
                     "death_x" }) do
  GALLERY[#GALLERY + 1] = { anim = n }
end
for _, f in ipairs(FOES) do
  -- shown twice as big, if it fits
  local tall = 0
  for _, a in pairs(f.a) do
    for _, d in ipairs(a.d) do
      for _, fr in ipairs(d) do tall = max(tall, fr[6]) end
    end
  end
  f.zoom = tall <= 66 and 2 or 1
  for _, n in ipairs(f.order) do GALLERY[#GALLERY + 1] = { def = f, anim = n } end
end
local gal = { i = 1, wait = 0, o = { def = FOES[1], anim = "idle", f = 1, ft = 0, dir = 0, x = 0, y = 0 } }
local function gal_start()
  local g = GALLERY[gal.i]
  gal.wait = 0
  if g.def then
    gal.o.def = g.def
    FOE.play(gal.o, g.anim)
  else
    play(g.anim)
  end
end

function _init()
  -- the fade tables: every colour of the sheet at the 8 light levels.
  -- Level 1 is the night (dim, blue: the twilight of a dead town), 7 the
  -- warm light under a lamp; glass of lit windows, flames and embers keep
  -- their colour at every level: they make their own light.
  local rows = {}
  for _, c in ipairs(PALETTE) do
    local row = { c }
    local r, g, b = c >> 16, (c >> 8) & 255, c & 255
    local lum = 0.30 * r + 0.59 * g + 0.11 * b
    for k = 0, LEVELS - 1 do
      local o = c
      if not GLOWING[c] then
        local nr, ng, nb = r * 0.13 + lum * 0.03, g * 0.14 + lum * 0.05, b * 0.20 + lum * 0.12
        if k == 0 then nr, ng, nb = nr * 0.45, ng * 0.45, nb * 0.55 end
        local wr, wg, wb = min(255, r * 1.10 + 8), min(255, g * 0.97 + 2), b * 0.76
        local f = k <= 1 and 0 or ((k - 1) / (LEVELS - 2)) ^ 1.15
        local fr, fg, fb = nr + (wr - nr) * f, ng + (wg - ng) * f, nb + (wb - nb) * f
        o = ((floor(fr) // 8 * 8) << 16) | ((floor(fg) // 8 * 8) << 8) | (floor(fb) // 8 * 8)
      end
      row[k + 2] = o
    end
    rows[#rows + 1] = row
  end
  fades(rows)
  place_player()
  P.home = { P.x, P.y }
  cam_x, cam_y = P.x - W / 2, P.y - H * 0.62
end

function _update()
  t = t + 1
  if state == "title" then
    -- after a moment the camera drifts over the town: the hunter starts
    -- wherever it is when A is pressed
    if t > 150 then
      cam_x, cam_y = cam_x + 0.9, cam_y + 0.45
    end
    if btnp(4) or btnp(5) then
      state = "play"
      if t > 150 then start_here() end
    elseif btnp(6) then
      state, gal.i = "gallery", 1
      P.dir = 0
      gal_start()
    end
    if P.anim ~= "idle" then play("idle") end
    step_anim()
    FOE.update(true)
  elseif state == "gallery" then
    if btnp(0) then P.dir = (P.dir + 1) % 8 end
    if btnp(1) then P.dir = (P.dir + 7) % 8 end
    if btnp(2) or btnp(3) then
      gal.i = (gal.i + (btnp(3) and 0 or -2)) % #GALLERY + 1
      gal_start()
    elseif btnp(7) then
      -- Y: the next creature, at its first animation
      local cur = GALLERY[gal.i].def
      repeat gal.i = gal.i % #GALLERY + 1 until GALLERY[gal.i].def ~= cur
      gal_start()
    end
    local g = GALLERY[gal.i]
    gal.o.dir = P.dir
    if btnp(5) or btnp(6) then
      state, t = "title", 0
      play("idle")
    elseif gal.wait > 0 then
      gal.wait = gal.wait - 1
      if gal.wait == 0 then gal_start() end
    elseif (g.def and FOE.step(gal.o)) or (not g.def and step_anim()) then
      gal.wait = 40
    end
    return
  else
    update_play()
  end
  stream()
  if t % 15 == 0 then FOE.spawn_around() end
  update_parts()
end

----------------------------------------------------------------- drawing

local function draw_map()
  local tx0, ty0 = fdiv(cam_x, TS), fdiv(cam_y, TS)
  local tx1, ty1 = fdiv(cam_x + W - 1, TS), fdiv(cam_y + H - 1, TS)
  local ty = ty0
  while ty <= ty1 do
    local ry = ty % RT
    local nty = min(ty1 - ty + 1, RT - ry)
    local tx = tx0
    while tx <= tx1 do
      local rx = tx % RT
      local ntx = min(tx1 - tx + 1, RT - rx)
      map(rx * 2, ry * 2, tx * TS, ty * TS, ntx * 2, nty * 2)
      map(128 + rx * 2, ry * 2, tx * TS, ty * TS, ntx * 2, nty * 2)
      tx = tx + ntx
    end
    ty = ty + nty
  end
end

local vis = {}
local function by_depth(a, b) return a.z < b.z end     -- everything drawn in depth order has a z
local function visible_chunks(margin)
  local out = {}
  for cy = fdiv(cam_y - margin, CPX), fdiv(cam_y + H + margin, CPX) do
    for cx = fdiv(cam_x - margin, CPX), fdiv(cam_x + W + margin, CPX) do
      local ch = chunk(cx, cy)
      if ch and ch.ready then out[#out + 1] = ch end
    end
  end
  return out
end

local function draw_scene()
  local sx, sy = 0, 0
  if FOE.shake > 0 then sx, sy = math.random(-2, 2), math.random(-1, 1) end
  camera(cam_x + sx, cam_y + sy)
  draw_map()
  -- objects and the hunter, back to front
  local n = 0
  local x0, y0, x1, y1 = cam_x - 64, cam_y - 16, cam_x + W + 64, cam_y + H + 140
  local near = visible_chunks(140)
  for _, ch in ipairs(near) do
    for _, o in ipairs(ch.objs) do
      if o.bld then
        if o.x < cam_x + W and o.x + o.w * TS > cam_x and o.top < cam_y + H and o.y > cam_y then
          n = n + 1; vis[n] = o
        end
      elseif o.x > x0 and o.x < x1 and o.y > y0 and o.y < y1 then
        n = n + 1; vis[n] = o
      end
    end
  end
  if state ~= "title" or t <= 150 then
    n = n + 1
    vis[n] = P
    P.z = P.y
  end
  for _, o in ipairs(FOE.list) do
    if o.x > x0 and o.x < x1 and o.y > y0 and o.y < y1 then n = n + 1; vis[n] = o end
  end
  for i = n + 1, #vis do vis[i] = nil end
  table.sort(vis, by_depth)
  for i = 1, n do
    local o = vis[i]
    if o.bld then
      local c = o.bld
      local i0, i1 = max(0, fdiv(cam_x - o.x, TS)), min(o.w - 1, fdiv(cam_x + W - 1 - o.x, TS))
      local j0, j1 = max(0, fdiv(cam_y - o.top, TS)), min(o.h - 1, fdiv(cam_y + H - 1 - o.top, TS))
      for j = j0, j1 do
        local y = o.top + j * TS
        for i = i0, i1 do spr(c[j * o.w + i + 1], o.x + i * TS, y, 2, 2) end
      end
    elseif o.def then
      FOE.draw(o)
    elseif o == P then
      -- after a blow he blinks while he cannot be hurt
      if not (P.act == nil and P.inv > 0 and P.inv < 50 and (P.inv // 3) % 2 == 1) then
        local fr = HUNT[P.anim].d[P.dir + 1][P.f]
        sspr(fr[1], fr[2], fr[3], fr[4], floor(P.x) - fr[5], floor(P.y) - fr[6])
      end
    else
      local s = o.s
      if o.lamp and not lamp_state[o.lamp] then s = SPR.lamp_off end
      sspr(s[1], s[2], s[3], s[4], floor(o.x) - s[5], floor(o.y) - s[6])
    end
  end
  -- smoke: drawn before the lights, so only fires and lamps show it
  for _, p in ipairs(parts) do
    if p.kind == 3 then
      local a = p.t / p.life
      circfill(p.x, p.y, 1 + a * 4, a < 0.5 and 0x585058 or 0x403840)
    elseif p.kind == 5 then
      pset(p.x, p.y, p.t < 8 and 0xB82028 or 0x681018)
    end
  end
  -- the lights
  dark_begin(AMBIENT)
  local fire_near
  for _, ch in ipairs(near) do
    for _, l in ipairs(ch.lights) do
      local rr = l.r
      if l.fl > 0 then
        rr = rr * (1 - l.fl * 0.08 + l.fl * 0.05 * sin(t * 0.31 + l.seed) + l.fl * 0.04 * sin(t * 0.73 + l.seed * 3))
      end
      if l.x + rr > cam_x and l.x - rr < cam_x + W and l.y + rr > cam_y and l.y - rr < cam_y + H then
        glow(l.x, l.y, rr, l.lv, l.d)
      end
    end
    for _, l in ipairs(ch.lamps) do
      if lamp_state[l.key] then
        local rr = 64 + sin(t * 0.05 + l.x) * 1.0
        if l.x + rr > cam_x and l.x - rr < cam_x + W and l.y + rr > cam_y and l.y - rr < cam_y + H then
          glow(l.x, l.y - 6, rr, 7, 0.3)        -- concentric discs, as in Dank Tomb
        end
      end
    end
    for _, f in ipairs(ch.fires) do
      local dd = abs(f.x - P.x) + abs(f.y - P.y)
      if not fire_near or dd < fire_near then fire_near = dd end
    end
  end
  glow(P.x, P.y - 14, 42, 4, 0.7)               -- what the hunter's eyes make out
  FOE.lights()
  if flash > 0 then
    local fr = HUNT[P.anim].d[P.dir + 1][P.f]
    glow(P.x + fr[9], P.y + fr[10], 30 + flash * 9, 7, 0.4)
  end
  dark_end()
  -- the trail of the blade, the flash and the shot
  local tr = P.trail
  for i = 2, #tr do
    local a, b = tr[i - 1], tr[i]
    local c = b[3] > 7 and 0xF0F0E8 or b[3] > 4 and 0xB0B0C0 or 0x686878
    line(a[1], a[2], b[1], b[2], c)
    if b[3] > 5 then line(a[1], a[2] + 1, b[1], b[2] + 1, 0x9090A0) end
  end
  if flash > 0 then
    local fr = HUNT[P.anim].d[P.dir + 1][P.f]
    local mx, my = P.x + fr[9], P.y + fr[10]
    local v = DIRV[P.dir + 1]
    circfill(mx, my, flash > 3 and 3 or 2, 0xF8C050)
    circfill(mx, my, 1, 0xF8F8D8)
    if flash > 2 then
      line(mx, my, mx + v[1] * (6 + flash), my + v[2] * (6 + flash), 0xF8E890)
      line(mx - v[2] * 3, my + v[1] * 3, mx + v[2] * 3, my - v[1] * 3, 0xF89030)
    end
  end
  if tracer then
    line(tracer[1], tracer[2], tracer[3], tracer[4], tracer[5] > 3 and 0xF8E8A0 or 0x907050)
  end
  FOE.fx()
  if P.lock and state == "play" then FOE.mark(P.lock, FOE.visceral_target() and 0xF8F8E8 or 0xE04030) end
  -- flames and embers make their own light: drawn after it. First the
  -- white-hot heart of every fire, then the tongues and sparks
  for _, ch in ipairs(near) do
    for _, f in ipairs(ch.fires) do
      if f.x > cam_x - 32 and f.x < cam_x + W + 32 and f.y > cam_y - 32 and f.y < cam_y + H + 32 then
        local fl = sin(t * 0.37 + f.x) + sin(t * 0.91 + f.y)
        if f.big then
          circfill(f.x, f.y + 4, 9 + fl, 0xA83818)
          circfill(f.x - 3, f.y + 2, 6 + fl * 0.5, 0xE06020)
          circfill(f.x + 4, f.y + 3, 5 - fl * 0.5, 0xF89030)
          circfill(f.x, f.y, 4 + fl * 0.4, 0xF8C050)
          circfill(f.x, f.y - 1, 2, 0xF8F8D8)
        else
          circfill(f.x, f.y + 3, 4 + fl * 0.3, 0xE06020)
          circfill(f.x, f.y + 2, 3, 0xF8C050)
          rectfill(f.x - 1, f.y + 1, 2, 2, 0xF8F8D8)
        end
      end
    end
  end
  for _, p in ipairs(parts) do
    local k = p.kind
    if k == 1 then
      local a = p.t / p.life
      local c = FLAME[min(#FLAME, 1 + floor(a * #FLAME))]
      if a < 0.22 then rectfill(p.x - 1, p.y - 1, 3, 3, c)
      elseif a < 0.5 then rectfill(p.x, p.y, 2, 2, c)
      else pset(p.x, p.y, c) end
    elseif k == 2 then
      if (p.t // 3 + p.life) % 4 ~= 0 then pset(p.x, p.y, p.t < p.life * 0.6 and 0xF8B040 or 0xC05020) end
    elseif k == 4 then
      pset(p.x, p.y, 0xF8E8A0)
    end
  end
  camera()
  return fire_near
end

local function emit()
  for _, ch in ipairs(visible_chunks(48)) do
    for _, f in ipairs(ch.fires) do
      f.acc = (f.acc or 0) + f.rate
      while f.acc >= 1 do
        f.acc = f.acc - 1
        local x = f.x + (math.random() - 0.5) * 2 * f.w
        local y = f.y + (math.random() - 0.5) * (f.big and 16 or 4)
        spawn(x, y, (math.random() - 0.5) * 0.3, -0.5 - math.random() * (f.big and 1.1 or 0.7),
              14 + math.random(f.big and 30 or 16), 1)
        if math.random() < (f.big and 0.12 or 0.05) then
          spawn(x, y - 6, (math.random() - 0.5) * 0.6, -0.6 - math.random() * 0.8, 50 + math.random(60), 2)
        end
        if f.big and math.random() < 0.08 then
          spawn(f.x + (math.random() - 0.5) * 10, f.y - 40, 0.1, -0.35, 140, 3)
        end
      end
    end
    for _, s in ipairs(ch.smokes) do
      if math.random() < 0.06 then spawn(s.x + math.random(-1, 1), s.y, 0.05, -0.22 - math.random() * 0.1, 160, 3) end
    end
  end
end

local function shadow_print(s, x, y, c)
  print(s, x + 1, y + 1, 0x000000)
  print(s, x, y, c)
end

local GDIR = { "S", "SE", "E", "NE", "N", "NW", "W", "SW" }

local function draw_gallery()
  cls(0x101018)
  camera()
  circfill(128, 186, 30, 0x1C1C28)
  rectfill(98, 182, 61, 9, 0x1C1C28)
  local g = GALLERY[gal.i]
  local name
  rectfill(0, 16, W, 32, 0x000000)
  if g.def then
    local o, z = gal.o, g.def.zoom
    local fr, flip = FOE.frame(o)
    local x = flip and 128 - (fr[3] - fr[5]) * z or 128 - fr[5] * z
    sspr(fr[1], fr[2], fr[3], fr[4], x, 186 - fr[6] * z, flip, false, z)
    local title = g.def.title
    print(title, (W - #title * 8) // 2 // 8 * 8, 16, g.def.boss and 0xE07050 or 0xD8C8A0)
    name = g.anim .. "  " .. GDIR[P.dir + 1] .. "  " .. o.f .. "/" .. #g.def.a[g.anim].t
    print(name, (W - #name * 8) // 2 // 8 * 8, 32, 0xE8C878)
  else
    local fr = HUNT[P.anim].d[P.dir + 1][P.f]
    sspr(fr[1], fr[2], fr[3], fr[4], 128 - fr[5] * 2, 186 - fr[6] * 2, false, false, 2)
    name = g.anim .. "  " .. GDIR[P.dir + 1] .. "  " .. P.f .. "/" .. #HUNT[P.anim].t
    print(name, (W - #name * 8) // 2 // 8 * 8, 16, 0xE8C878)
  end
  rectfill(0, 224, W, 32, 0x000000)
  print("left right: turn  Y: next", 24, 224, 0x8890A0)
  print("up down: animation  B: back", 16, 240, 0x8890A0)
end

function _draw()
  if state == "gallery" then
    draw_gallery()
    return
  end
  emit()
  local fire_near = draw_scene()
  if state == "title" then
    if t <= 150 then
      rectfill(0, 16, W, 48, 0x000000)
      print("YHARNAM", 96, 16, 0xE8C878)
      print("a town of endless night", 40, 32, 0x8890A0)
      print("X: animations", 72, 48, 0x686878)
      rectfill(0, 208, W, 48, 0x000000)
      print("A blow  R1 heavy  L1 lock", 24, 224, 0x8890A0)
      print("B dodge  X gun  Y trick", 32, 240, 0x8890A0)
    else
      rectfill(0, 208, W, 16, 0x000000)
    end
    print("A: START", 96, 208, (t // 30) % 2 == 0 and 0xE8E0D0 or 0x988870)
  elseif state == "gallery" then
    -- drawn by draw_gallery
  else
    update_sound(fire_near)
    if banner_t > 0 and banner then
      local w = #banner * 8
      local x = (W - w) // 2 // 8 * 8
      rectfill(x - 8, 16, w + 16, 16, 0x000000)
      print(banner, x, 16, banner_t > 30 and 0xD8C8A0 or 0x786850)
    end
    if near_lamp then
      rectfill(48, 224, 160, 16, 0x000000)
      print("A: light the lamp", 56, 224, 0xE8C878)
    end
    if lamps_lit > 0 then
      shadow_print("lamps " .. lamps_lit, 8, 240, 0xC8A060)
    end
    if FOE.killed > 0 then
      local s = "prey " .. FOE.killed
      shadow_print(s, W - 8 - #s * 8, 240, 0xC8A060)
    end
    FOE.hud()
    -- health: a red bar, as the hunters have
    rectfill(7, 7, HP_MAX * 7 + 2, 6, 0x100808)
    if P.hp > 0 then rectfill(8, 8, P.hp * 7, 4, P.inv > 40 and 0xE04030 or 0xA01818) end
    if P.rally > 0 and P.hp > 0 then rectfill(8 + P.hp * 7, 8, min(P.rally, HP_MAX - P.hp) * 7, 4, 0xC87028) end
    -- stamina, green, under it
    rectfill(7, 14, ST_MAX * 0.7 + 2, 4, 0x081008)
    if P.st > 0 then rectfill(8, 15, floor(P.st * 0.7), 2, P.st_wait > 0 and 0x488838 or 0x68B050) end
    if P.act == "dead" and died_t > 0 then
      local k = min(died_t, 40)
      rectfill(0, 104, W, 48, 0x080404)
      print("YOU DIED", 64, 112, k > 20 and 0xA01818 or 0x501010, 2)
    end
  end
end
